quests[6364] = { id = 6364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Varg", description = "Um zu einer Stadt zu fliegen, müsst Ihr schon einmal dort gewesen sein und mit dem Windreitermeister dieser Stadt gesprochen haben. Ihr seid beim Dorf der Bluthufe gewesen und habt mit dem Windreitermeister Tak gesprochen, daher könnt Ihr gegen ein geringes Entgelt von hier mit einem unserer Windreiter zu ihm fliegen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. Im Dorf der Bluthufe könnt Ihr die Lederwaren zu Varg Windraunen bringen.", sourceObjective = "Bucht einen Windreiter zum Dorf der Bluthufe bei Windreitermeister Tak und bringt dann Ahanus Lederwaren zu Varg Windraunen.", progress = "{name}, Ihr seid aus Thunder Bluff zurück? Habt Ihr die Bälge zu Ahanu gebracht?", completion = "Ahanu schickt mir fertige Produkte? Sehr gut. In Crossroads wimmelt es gerade von Jägern und Abenteurern und die Geschäfte gehen blendend. Ich bin sicher, ich kann diese Waren im Handumdrehen an den Mann bringen.\n\nVielen Dank für all Eure Bemühungen, {name}. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[6365] = { id = 6365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch für Orgrimmar", description = "Ich habe hier ausgewählte Fleischstücke, die ich einer Freundin schicken möchte. Ihr Name ist Gryshka, sie ist die Gastwirtin in Orgrimmar. Würdet Ihr das Fleisch für mich abliefern?\n\nDas schnellste Transportmittel nach Orgrimmar ist ein Windreiter. Bringt das Fleisch zu Windreitermeister Burok in Klingenhügel und sprecht mit ihm über den Transport nach Orgrimmar.", sourceObjective = "Bringt Grimtaks Fleisch zu Burok in Klingenhügel.", progress = "Ihr wollt schnell irgendwohin? Tja, dann sprecht Ihr mit dem richtigen {race}!", completion = "Ihr müsst dieses Fleisch nach Orgrimmar bringen? Das ist kein Problem. Für ein bescheidenes Sümmchen kann mein Windreiter Euch hinbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6381] = { id = 6381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Leben", description = "Wie Ihr sehen könnt, {class}, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im Verbrannten Tal. Aber seid wachsam, denn Harpyien und Feuerelementare verseuchen das vernarbte Land noch immer.\n\nNehmt diese verzauberten Gaeasamenkörner und pflanzt sie in fruchtbare Erdhügel, {name}. Der Zyklus des Lebens muss weitergehen!", sourceObjective = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und bringt Tammra in Sonnenfels dann die restlichen verzauberten Gaeasamenkörner zurück.", progress = "Diese Samenkörner, die Ihr pflanzt, sind stark, widersetzen sich der Verderbnis und schaffen neuen Platz für anderes Leben. Sie werden wachsen und wachsen, zuerst die Verderbnis verhindern und das vernarbte Land heilen, und dann werden sie eines Tages das Steinkrallengebirge wieder zu einem üppigen Wald machen.\n\nHabt Ihr alle Gaeasamenkörner gepflanzt?", completion = "Das ist ein großer Sieg für das Land. Mit der Zeit werden auch andere Dinge geschehen: Die Venture Company wird die Kreissägen und Äxte zusammenpacken, die wütenden Feuergeister werden sich beruhigen und die Harpyien werden vom Land vertrieben.\n\nErst dann, {name}, wird das Steinkrallengebirge wirklich Frieden finden.\n\nIhr habt Eure Sache gut gemacht, {class}. Nehmt einen dieser Gegenstände als Dank für das neue Leben, das Ihr heute hier geschaffen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6382] = { id = 6382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd im Eschental", description = "Eure Kraft beeindruckt mich, {class}. Die Entschlossenheit, mit der Ihr Euch der Jagd zuwendet, erfüllt mich mit der Gewissheit, dass Ihr Euch größerem Wild... und größeren Herausforderungen zuwenden könnt.\n\nDer Wald des Eschentals ist eine große, ungezähmte Wildnis, der die Horde ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Wenn Ihr Euch in einem unerforschten Land beweisen wollt, dann sucht die Führung von Senani Donnerherz im Splitterholzposten. Der Außenposten liegt nördlich des Pfads, der aus dem Brachland führt.", sourceObjective = "Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental.", completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[6383] = { id = 6383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd im Eschental", sourceObjective = "Es gibt drei legendäre Kreaturen, die die Jagd in Ashenvale bilden. Ihr könnt sie suchen und Euch mit ihrer List und Kraft messen. Dabei werdet Ihr hoffentlich auch etwas über Euch selbst lernen. Die Kreaturen sind: der Bär Ursangus, die Nachtsäblerkatze Schattumbra und der Hippogryph Scharfkralle.\n\nDie Kreaturen der Jagd in Ashenvale sind mächtig; möglicherweise benötigt Ihr Unterstützung, um sie zu bezwingen. Wenn Ihr sie besiegt habt, dann bringt mir Beweise Eurer Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[6384] = { id = 6384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Orgrimmar", description = "Für eine Handvoll Münzen lasse ich Euch mit einem Windreiter nach Orgrimmar bringen. Wenn Ihr dort eintrefft, bringt Grimtaks Fleisch zu Gryshka. Ihr Gasthaus liegt im Tal der Stärke.\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", sourceObjective = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Burok und bringt dann Grimtaks Fleisch zu Gryshka in Orgrimmar.", progress = "Irgendwas riecht lecker! Ihr habt nicht zufällig rohes Fleisch bei Euch, oder?", completion = "Wie wundervoll! Das ist bestes Filet! Es ist von Zargh, richtig? Dieser {race} versteht es, das Herz einer Dame zu betören...\n\nOh, ich kann es kaum erwarten, das zuzubereiten. Aber nicht zu viel! Fleisch serviert man am besten selten, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[6385] = { id = 6385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doras der Windreitermeister", description = "Ich habe Grimtak einen Dankesbrief geschrieben. Könnt Ihr ihn für mich zustellen? Wenn Ihr schon beim Klingenhügel gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem Windreiter dorthin zurück fliegen.\n\nBringt meinen Brief zu Doras, dem Windreitermeister von Orgrimmar und sprecht mit ihm über den Transport nach Klingenhügel.", sourceObjective = "Bringt Gryshkas Brief zu Doras in Orgrimmar.", progress = "Braucht Ihr einen meiner Windreiter?", completion = "Ihr müsst das nach Crossroads im Brachland bringen? Ja, ich kann Euch dorthin bringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6386] = { id = 6386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt nach Klingenhügel zurück", description = "Meine Windreiter wurden ausgebildet, an viele verschiedene Orte zu fliegen, wenn Ihr schon an diesem Ort gewesen seid und mit dem Windreitermeister dort gesprochen habt.\n\nIhr seid in Klingenhügel gewesen und habt mit dem Windreitermeister Burok gesprochen, daher könnt Ihr jetzt direkt zu ihm fliegen. Wenn Ihr in Klingenhügel seid, könnt Ihr Gryshkas Brief zu Grimtak bringen.\n\nSprecht wieder mit mir, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Bucht einen Windreiter zum Klingenhügel bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Grimtak in Klingenhügel.", progress = "Seid Ihr von Orgrimmar zurück? Hat Gryshka das Fleisch geschmeckt, das ich ihr geschickt habe?", completion = "Ha! Natürlich hat es ihr geschmeckt! Nichts macht die Wangen einer Dame so rot wie ein großes, saftiges Steak!\n\nDanke, {name}. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr etwas Geld für Eure Mühe, und seid nicht überrascht, wenn ich Euch zu meiner Hochzeit einlade!", sourceObjectiveStatus = "unverified-source-field" }
quests[6387] = { id = 6387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenlehrlinge", description = "Ich sehe viele junge Zwerge vor meiner Tür, die begierig sind, die Kochkunst zu erlernen. Und wenn ein Koch eines mehr als alles andere braucht, dann ist das ein Beil!\n\nIch habe eine Liste von Kochlehrlingen mit vorzüglichen Abschlussprüfungen, die sich ein Ehrenbeil verdient haben. Bringt meine Liste zu Golnir Geröllzeh in Eisenschmiede. Er wird die Beile bereitstellen.\n\nDas schnellste Transportmittel nach Eisenschmiede ist ein Greif, also bringt die Liste Brolan Windbart, unserem Greifenmeister, und sprecht mit ihm über den Transport nach Eisenschmiede.", sourceObjective = "Bringt Gremlocks Liste zu Brolan Windbart in Kharanos.", progress = "Habt Ihr schon so bald die Nase voll von Thelsamar? Seid Ihr bereit, in eine andere Stadt abzureisen?", completion = "Ihr müsst das nach Ironforge bringen, hm? Für ein geringes Entgelt setze ich Euch auf den Rücken eines meiner Greife, der Euch dorthin bringt. Na, was sagt Ihr dazu?", sourceObjectiveStatus = "unverified-source-field" }
quests[6388] = { id = 6388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryth Thurden", description = "Hier sind die Ehrenbeile für Gremlocks Schüler. Wenn Ihr schon in Kharanos gewesen seid, dann solltet Ihr mit einem Greifen dorthin zurückfliegen!\n\nBringt die Beile zu unserem Greifenmeister Gryth Thurden und sprecht mit ihm über die Rückreise nach Kharanos.", sourceObjective = "Bringt die Ehrenbeile zu Gryth Thurden in Eisenschmiede.", progress = "Ihr seht aus, als müsstet Ihr irgendwohin. Braucht Ihr einen meiner Greifen?", completion = "Ihr müsst das nach Thelsamar bringen, hm? Das wird gar kein Problem sein. Wenn Ihr schon in Thelsamar gewesen seid und mit Thorgrum Borrelson gesprochen habt, dann könnt Ihr einen meiner Greifen zurück zu ihm nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6389] = { id = 6389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", sourceObjective = "Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestlandtermiten zu Nathaniel Dumah im Zugwindlager in den Westlichen Pestländern zurück.", progress = "Habt Ihr es geschafft, {name}? Habt Ihr die Termiten freigelassen? Das Licht stehe uns bei, wenn der Scharlachrote Kreuzzug sowohl das Werk wie auch Hearthglen halten könnte. Beides hätte nicht gelingen sollen. Sie beuten lediglich die Opfer des letzten Kriegs aus und sollten erlegt werden wie tollwütige Tiere!", completion = "Haha! Danke, {name}! Ihr habt es geschafft! Meines Vaters Geist findet jetzt Ruhe und ich kann in Frieden leben.\n\nNochmals danke. Wenn ich etwas für Euch tun kann, so sagt es bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[6390] = { id = 6390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", sourceObjective = "Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück.", progress = "Habt Ihr es geschafft, {name}? Habt Ihr die Termiten im Sägewerk freigelassen?\n\nEs war schlimm genug, dass meine Familie Arbeit und Leben verlor, aber dann mit anzusehen, wie der Ort, wo ich meine Kindheit verbrachte, von diesen widerwärtigen sogenannten heiligen Männern übernommen wurde ... bäh!!!", completion = "Danke, {name}. Hier, nehmt diese Münze. Leider habe ich nicht mehr, aber freut Euch wenigstens darüber, dass Ihr die Bemühungen des Scharlachroten Kreuzzugs durchkreuzt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[6391] = { id = 6391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Eisenschmiede", description = "Für nur ein paar Münzen bringt Euch einer meiner Greifen nach Eisenschmiede. Bringt dann Gremlocks Liste zu Golnir Geröllzeh. Ihr findet ihn in der Tiefenbergbaugilde. Sie liegt im Distrikt der Großen Schmiede von Eisenschmiede, und genau dort setzt Euch mein Greif ab!\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", sourceObjective = "Bucht einen Greifen nach Eisenschmiede von Greifenmeister Brolan Windbart, dann bringt Gremlocks Liste zu Golnir Geröllzeh in Eisenschmiede.", progress = "Womit kann ich Euch dienen, werter Herr?", completion = "Ah, die neueste Liste von Brocks Meisterschülern. Ich habe schon ein paar Ehrenhacken bereit. Ich muss nur noch die Namen der Studenten eingravieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[6392] = { id = 6392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Gremlock", description = "Für ein geringes Entgelt könnt Ihr einen Greifenritt nach Kharanos buchen... wenn Ihr schon einmal dort gewesen seid. Greifen fliegen nur zu Orten, an denen Ihr schon einmal gewesen seid, sprecht also mit jedem Greifenmeister, den Ihr seht, dann könnt Ihr später direkt zu ihm fliegen.\n\nIhr seid schon bei Brolan, dem Greifenmeister von Kharanos, gewesen, daher könnt Ihr jetzt zu ihm zurückkehren. Wenn Ihr in Kharanos seid, könnt Ihr Gremlock Pilsnor die Beile bringen.\n\nSprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", sourceObjective = "Bucht einen Greifen nach Kharanos bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Gremlock Pilsnor in Kharanos.", progress = "Ah, {name}. Ihr seid aus Ironforge zurück.", completion = "Ihr habt die Hacken. Großartig! Ich werde sie meinen Bergbaustudenten bringen. Sie können es sicher kaum erwarten, sich damit auf die Erzvorkommen von Loch Modan zu stürzen.\n\nDanke für Eure Hilfe, {name}. Ich stehe in Eurer Schuld, hoffe jedoch, dieses Geld wird wenigstens Eure Reisekosten decken.", sourceObjectiveStatus = "unverified-source-field" }
quests[6393] = { id = 6393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg der Elementare", description = "Das Tribunal der Gezeiten hat mich geschickt, um den Feuerelementaren hier im Steinkrallengebirge den Krieg zu erklären. Neptulon der Gezeitenjäger, der Lord aller Wasserelementare hier, hat ein persönliches Interesse daran, dass unsere feurigen Vettern ausgelöscht werden.\n\n{name}, Ihr könnt mir helfen, die Gunst des Tribunals zu erringen, indem Ihr die Feuerelementare im Verbrannten Tal vernichtet. Wenn Feuerelementare zerstört werden, hinterlassen sie Pyrophore. Bringt sie mir, dann werde ich Euch belohnen.", sourceObjective = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", progress = "Das Tribunal der Gezeiten wird ungeduldig. Es will diesen Krieg beenden, der seit Äonen durch alle Dimensionen wütet. Meine Brüder brennen darauf, dass man ihnen endlich den ruhmreichen Sieg über die verhassten Feuerelementare meldet. Habt Ihr die Pyrophore, die ich benötige?", completion = "Die Wassergeister in mir prickeln vor Aufregung. {name}, durch Euren Einsatz kann ich dem Tribunal der Gezeiten nun einen glorreichen Sieg vermelden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6394] = { id = 6394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'rils Hacke", description = "{name}, Ihr seid <ein/eine:r> {race}, auf <den/die:r> man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Brennenden Klinge, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", sourceObjective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", progress = "Habt Ihr den Koven der Burning Blade betreten, {name}? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, {name}. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", sourceObjectiveStatus = "unverified-source-field" }
quests[6395] = { id = 6395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlas letzter Wunsch", description = "Meine Freundin Marla Fipps lebte vor der Seuche mit ihrem Mann Samuel zusammen, doch als die Seuche kam, erlag Samuel ihr und lief zur Geißel über.\n\nMarla wurde der Untod erspart, doch sie starb durch die Hand ihres jetzt hirnlosen Mannes. Aber ihre Liebe war so stark, dass sie sterbend den letzten Wunsch äußerte, zusammen mit ihrem geliebten Samuel begraben zu werden.\n\nSamuel Fipps streift durch ein verwüstetes Lager nordöstlich von Todesend. Besiegt ihn und erfüllt Marlas Wunsch: Begrabt ihn in ihrem Grab in der ersten Reihe unseres Friedhofs.", sourceObjective = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novizin Elreth zurück.", progress = "Wir müssen unsere Toten achten, {name}. Darin unterscheiden wir uns von der Geißel...", completion = "Ihr habt heute eine gute Tat vollbracht, {name}. Der Kampf gegen die Geißel geht zwar weiter, aber hoffen wir, dass Marla und Samuel gemeinsam Frieden in ihrer letzten Ruhestätte finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6401] = { id = 6401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaya lebt", description = "Teilt Tammra Windfeld, Kayas Tante, die in Sonnenfels lebt, die gute Nachricht mit! Kaya lebt! Wir hatten sie nach dem brutalen Angriff auf unser Dorf schon verloren geglaubt. Folgt dem Pfad nach Westen, um nach Sonnenfels zu gelangen.", sourceObjective = "Teilt Tammra Windfeld, die in Sonnenfels lebt, die gute Nachricht mit.", completion = "Dem Himmel sei Dank, meine Nichte Kaya lebt! Das sind wahrlich gute Neuigkeiten. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6402] = { id = 6402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen in Sturmwind", description = "Ihr sollt Euch an den Toren von Sturmwind mit Windsor treffen.\n\nWas Windsor Euch eröffnen wird, wird das gesamte Königreich in den Grundfesten erschüttern!\n\nVersucht aber nicht, allein dorthin zu gehen, {name}. Ihr müsst eine ganze Armee zusammenscharen! Versammelt Eure Mitstreiter. Zu den Waffen!", sourceObjective = "Reist nach Sturmwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marschall Windsor über Eure Ankunft informiert.", completion = "Bevor wir beginnen, bitte ich Euch, dass Ihr zuerst eine Armee zusammenzieht. Wir haben es hier schließlich mit einem Drachen zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[6403] = { id = 6403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Maskerade", description = "Das war vielleicht ein Abenteuer. Ich schulde Euch großen Dank. Vielleicht, wenn alles gesagt und getan ist...\n\nWie Ihr zweifellos schon bemerkt haben werdet, sind Lady Prestor und Onyxia ein und dieselbe Person. Sie ist die Brut von Todesschwinge, Zwillingsschwester des Tyrannen der Spitze, Nefarian.\n\nViel zu lange schon hat sie ihren gierigen Blick auf unser Königreich gerichtet. Sogar der Hochlord steht schon unter dem Bann ihrer Zaubertricks - eine Marionette. Heute wird damit Schluss gemacht... Der Bann wird gebrochen.\n\nSorgt Euch nicht, denn gemeinsam werden wir siegen!\n\nSeid Ihr bereit?", sourceObjective = "Folgt Reginald Windsor durch Sturmwind. Schützt ihn vor Gefahren!", progress = "Ich... Ich... Ich war machtlos.", completion = "<Bolvar hält das zertrümmerte Medaillon in den Händen.>\n\nDie Magie darin muss wieder entfacht werden. Das Großdrachenauge muss eingestellt werden.\n\nWindsors Opfer hat unser Königreich befreit, aber die Bedrohung durch Onyxia und ihresgleichen besteht immer noch.\n\nDieses Medaillon hielt meinen Geist und meinen Körper gefangen. Es ließ mich jedoch auch in Onyxias Geist blicken - zeigte mir ihre Geheimnisse. Die Visionen sind zwar jetzt etwas verschwommen, aber an manche Dinge erinnere ich mich doch.", sourceObjectiveStatus = "unverified-source-field" }
quests[6421] = { id = 6421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinschlagklamm", description = "Irgendetwas stimmt hier im Steinkrallengebirge nicht. Spürt Ihr die Spannung, die in der Luft liegt, {name}?\n\nSüdlich von hier liegt eine tiefe Höhle in der Steinschlagklamm. Die Kobolde dort schürfen wie wild nach einem seltenen Kristall, dem so genannten Resonit. Ich möchte, dass Ihr mir ein paar Erzproben bringt, damit ich herausfinden kann, was in dieser Höhle vor sich geht. Ich hätte auch gern, dass Ihr die Tiefen dieser Höhle untersucht.\n\nGeht nun, {class}, es ist von größter Bedeutung, dass ich in Erfahrung bringe, welche Bösartigkeiten unter diesen Bergen lauern.", sourceObjective = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", progress = "Was habt Ihr in der Steinschlagklamm in Erfahrung bringen können? Ich erinnere mich an eine Legende, die irgendwas mit Resonit zu tun hatte... Ich komme nur nicht darauf. Vielleicht wird es etwas Licht auf ihre verschlagenen Absichten werfen, wenn wir erst wissen, was auf dem Grund der Höhle liegt.", completion = "Ah... ja! Das ist es. Die Resonitkristalle enthalten eine Spur Erdmagie. Die Kobolde müssen sehr tief gegraben haben, um einen Irdenen zu finden.\n\nDen Legenden nach sind die Irdenen Kreaturen, die von den Titanen geschaffen wurden. Sie erschufen das Land, auf dem wir heute stehen. Das ist wahrlich eine Bedrohung, die wir nicht ignorieren dürfen.\n\n<Mor'rogal schüttelt seinen Kopf.>\n\nVielleicht kann ich diese Erzproben verzaubern, um sie gegen die üblen Pläne der Kobolde zu verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6441] = { id = 6441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrhörner", description = "He! Ich bin auf der Durchreise nach Ratschet, habe das ganze Eschental durchquert und mich entschlossen, hier im Splitterholzposten Rast zu machen. Ich suche immer nach guten Gelegenheiten und es scheint mir, dass in Ratschet zurzeit Satyrhörner sehr gefragt sind.\n\nNachdem ich mich hier ein bisschen umgehört habe, glaube ich, dass die Satyrn in der Nachtflucht, Satyrnaar und Xavian genau die Art Hörner besitzen, die ich suche. Ich kann mich mit diesen Satyrn nicht messen... aber Ihr!\n\nIch sag Euch was: Wenn Ihr mir die Hörner bringt, soll es Euer Schaden nicht sein.", sourceObjective = "Sammelt für Pixel im Splitterholzposten 16 Satyrhörner.", progress = "Ich hoffe, Ihr könnt mir bald ein paar dieser Hörner besorgen, {name}. Ich muss in Kürze nach Ratchet zurück!", completion = "Die sind perfekt, {name}! Danke, dass Ihr mir geholfen habt!\n\nOh, und das hier ist für Eure Mühen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6442] = { id = 6442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Naga am Zoramstrand", description = "Entlang der Küste hier lauert das Böse, {race}.\n\nSie ist die Ruhestätte der untergegangenen Stadt Zoram, die vor langer Zeit zerstört wurde und im Meer versank. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Die Gründe sind jedoch auch nicht weiter wichtig. Wir müssen das Land verteidigen, um das wir so hart gekämpft haben.\n\nBringt mir 20 ihrer Köpfe! Treibt die Naga in die Tiefen zurück!", sourceObjective = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", progress = "Die Naga werden immer mehr, {name}. Bitte erledigt diese Aufgabe für mich.", completion = "Wir könnten mehr Eures Schlags hier brauchen, {name}. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6461] = { id = 6461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfresser", description = "Wir Trolle hier am Malaka'jin haben von dem Land profitiert. Das Steinkrallengebirge bietet reiche Jagdgründe, von denen wir leben können.\n\nIn letzter Zeit jedoch scheinen wir die falschen Gäste angezogen zu haben... Die Spinnen in diesen Bergen haben nachts unsere Lager überfallen, um uns unsere Jagdbeute zu stehlen.\n\nWenn Ihr uns helfen könntet, diese schrecklichen Bestien zu töten, würden wir hier am Malaka'jin zutiefst in Eurer Schuld stehen. Die Spinnen sind überall im Steinkrallengebirge - geht einfach von hier aus nach Norden, dann werdet Ihr sehen, was ich meine.", sourceObjective = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", completion = "Toll! Gute Neuigkeiten: Vielleicht haben wir heute Nacht ein paar ungebetene Tafelgäste weniger.\n\nVielen Dank, {name}. Wir stehen für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[6462] = { id = 6462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollglücksbringer", description = "Meine Leute waren mit vielen hochheiligen Trollglücksbringern im Gepäck unterwegs, aber dann wurden sie von Distelfellfurbolgs angegriffen und getötet, bevor sie Zoram'gar erreichen konnten! Diese elenden Furbolgs!\n\nIch vermisse meine getöteten Brüder und Schwestern, aber wir werden uns im Jenseits wiedersehen. Die Trollglücksbringer haben in dieser Welt jedoch hohen Wert. Es ist eine Schande, dass sie jetzt in den Händen der Furbolgs sind!\n\n{name}, Ihr müsst diese Glücksbringer zurückholen! Sie befinden sich in Kisten in der Höhle, einer Höhle der Distelfelle am Ende des Lagers der Distelfelle nördlich von Astranaar.", sourceObjective = "Bringt Mitsuwa bei Höllschreis Wacht 8 Trollglücksbringer.", progress = "Habt Ihr die Glücksbringer gefunden, {name}? Jede Sekunde, die die Furbolgs im Besitz dieser heiligen Gegenstände sind, bringt mein Blut mehr zum Kochen!", completion = "Ihr habt sie gefunden! Danke! Danke, {name}! Ihr wisst ja gar nicht, welch großen Dienst Ihr mir erwiesen habt.\n\nEin Troll ohne Glücksbringer ist wie ein Orc ohne Kampfnarben...\n\nWertlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[6481] = { id = 6481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Irdene erhebt sich", description = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, {class}. Der Resonitbehälter, den Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.\n\nIch habe die Mixtur der Resonitkristalle, die Ihr gesammelt habt, mithilfe meiner Schamanenkräfte verändert. Nehmt den verzauberten Resonitkristall und zerschmettert den Resonitbehälter, in dem sich der Irdene befindet.\n\nWenn Goggeroc erwacht, wird er noch geschwächt sein... erschlagt ihn, {name}!", sourceObjective = "Öffnet den Resonitbehälter mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", progress = "Ich fürchte, dass das ganze Steinkrallengebirge verloren ist, wenn wir diese Bedrohung nicht umgehend beseitigen. Die Macht eines Irdenen ist ohnegleichen. Wenn Goggeroc erwacht, wird er nach seinem langen Schlummer noch geschwächt sein. Das ist die Gelegenheit, die Ihr ergreifen müsst...Geht jetzt, {name}!", completion = "Das sind gute Neuigkeiten, {class}! Ich fürchte mich vor dem, was ein Irdener in Kalimdor anrichten könnte.\n\nGoggeroc zu töten war eine Tat, die eines Helden würdig ist. Das habt Ihr gut gemacht. Die Bewohner des Steinkrallengebirges und Kalimdors stehen in Eurer Schuld, {class}.\n\nNehmt dies als Belohnung, oh Ehrwürdiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[6482] = { id = 6482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Ruul", description = "Huch? Wer seid Ihr?\n\n{name}? Ihr seid kein Furbolg. Sie sind verflucht! Sie haben mich für einen Bären gehalten und mich eingefangen. Jetzt lassen sie mich verhungern! Meine Kraft schwindet...\n\nHelft mir zu entkommen, dann sprecht mit meiner Schwester Yama im Splitterholzposten im Osten.\n\n{name}! Ich muss entkommen!", sourceObjective = "Begleitet Ruul und sprecht dann mit Yama Schneehuf im Splitterholzposten.", completion = "Ihr habt meinen Bruder gefunden! Er wurde vom Distelfellstamm gefangen? Das ist ja schrecklich, denn viele Furbolgs sind zwar edle Kreaturen, aber die Distelfelle sind verderbt.\n\nVielen Dank, dass Ihr meinen Bruder gerettet habt, {name}. Ich wage gar nicht darüber nachzudenken, wie sie den armen Ruul wohl behandelt haben. Er wird nach diesem Martyrium bestimmt eine ganze Weile schlafen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[6501] = { id = 6501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Großdrachenauge", description = "Ich habe leider nicht mehr als ein Fragment des zertrümmerten Medaillons zu bieten.\n\nIhr müsst einen anderen aus dem Geblüt der Großdrachen finden, der bereit ist, Euch zu helfen, einen neuen Schlüssel zu schmieden. Sobald Ihr diesen Schlüssel habt, müsst Ihr zum Drachensumpf in den Düstermarschen reisen. Dort findet Ihr ihr Lager, {name}.\n\nWo Ihr weitere Klans finden könnt, die gewillt wären, Euch zu helfen? Das weiß ich leider nicht...Es soll angeblich welche geben. Einige sollen sogar unter uns leben und arbeiten, getarnt als Angehörige der humanoiden Völker. Ich wünsche Euch Glück.", sourceObjective = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.", progress = "Ich spüre eine Aura des Bösen, die von Euch ausgeht, {race}. Was könntet Ihr besitzen, das eine solche Aura ausstrahlt?", completion = "Ich hätte es wissen müssen... ein Stück der schwarzen Großdrachenbrutmutter Onyxia. Wie widerlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[6502] = { id = 6502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenfeueramulett", description = "Das ist ein Stück des Großdrachen. Eine Schuppe - verzaubert und transformiert. Als Ganzes hätte sie Zugang zum Hort der Bestie verschafft. Zertrümmert ist sie nutzlos.\n\nEs ist möglich, den Gegenstand zu reparieren, aber dazu wäre das Blut eines schwarzen Großdrachenhelden erforderlich. Es gibt einen... Er ist bekannt als General Drakkisath, Herrscher über die Drachenbrutarmeen von Nefarian. Vielleicht habt Ihr schon von ihm gehört?\n\nBringt mir sein Blut, {race}, dann verzaubere ich das Fragment in etwas, das Euch Zugang zu Onyxias Hort verschaffen wird.", sourceObjective = "Ihr müsst das Blut des schwarzen Drachenhelden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Schwarzfelsspitze.", progress = "Der Fluss der Zeit hält niemals an oder wird auch nur um etwas langsamer, {race}. Mein Leben dauert ewig, Eures jedoch nicht. Vergeudet die Zeit nicht, die Euch noch bleibt...", completion = "Dieses Amulett gewährt Euch den Zugang, auf den Ihr aus seid. Onyxias Hort befindet sich in den Marschen von Dustwallow. Solange Ihr das Amulett habt, können ihre Zauberschütze Euch nicht am Eintreten hindern.\n\nDer blaue Drachenschwarm wünscht Euch Glück, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6503] = { id = 6503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kundschafter des Eschentals", description = "Verdammte Elfen! Die wusst'n genau, wo sie zuschlag'n mussten!\n\nDas war'n diese Kundschafter... Ich hab' ja versucht, sie zu warnen, dass wir bespitzelt werd'n, aber es wollte ja keiner auf mich hör'n. Und jetzt steh'n wir da: eingepfercht wie die Hühner!\n\nIs aber nie zu spät für Rache, Mann! Bringt sie zur Strecke und lasst sie zahlen für das, was sie uns angetan haben!", sourceObjective = "Tötet 9 Kundschafter des Eschentals.", completion = "Sehr gut, {name}. Eure Jagdkünste sind beeindruckend...\n\nDer Verlust dieser Kundschafter wird helfen, die Allianz ihrer Augen zu berauben, und wenn sie keine Informationen mehr bekommt, wird sie wohl kaum weiter angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6504] = { id = 6504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Seiten", description = "Ich habe gerade diesen Schredder in Ratschet abgeholt und war auf dem Heimweg ins Holzfällerlager des Kriegshymnenklans, in dem ich eigentlich Dienst verrichten sollte. Man hat mir eine Anleitung zur Bedienung des Schredders mitgegeben, aber auf dem Rückweg hat ein starker Windstoß sie mir aus den Händen geweht. Die Seiten sind überallhin geflogen und mir blieb nur noch der Einband.\n\nDie Seiten könnten mittlerweile überall sein, nehme ich an...aber ich weiß nicht, wie ich den Schredder ohne sie benutzen soll! Würdet Ihr sie für mich suchen?", sourceObjective = "Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen. Bringt die Seiten zu Gurda Zornnarbe in der Nähe des Splitterholzpostens zurück.", progress = "Hoffentlich findet Ihr die Seiten bald, {name}! Ich muss wirklich wieder zurück an die Arbeit!", completion = "Lesen ist nicht gerade meine Stärke... aber jetzt kann ich endlich wieder zurück an die Arbeit! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[6521] = { id = 6521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Malcin behauptet, dass er sich abseits der Hügel der Klingenhauer aufhalte. Dieser Botschafter muss getötet werden - seine Mission für den Lichkönig muss fehlschlagen.\n\nSeine Anwesenheit dort erklärt vieles von dem, was wir über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.\n\nSucht Malcin und tötet ihn, {name}. Kommt zurück, wenn Ihr das erledigt habt.", sourceObjective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", progress = "Habt Ihr den Botschafter gefunden, {name}? Ist er tot?\n\nWir können es uns nicht leisten, dass die Geißel in Kalimdor Fuß fasst. Sie ist bereits schon gefährlich genug für unsere eigenen Grenzen, ein Zweifrontenkrieg wäre zu gefährlich.\n\nDas einzig Positive an den Ereignissen, von denen Ihr mir erzähltet, ist, dass die Greisin nicht verderbt zu sein scheint. Sie muss tief in ihrem Herzen wissen, dass die Geißel große Macht bringen kann, dass das Brachland jedoch nicht wirklich ihr gehören würde, wenn sie sich auf den Handel einließe.", completion = "Gut. Gut gemacht, {class}.\n\nDa Malcin jetzt tot ist, wissen wir zumindest, dass der Vormarsch der Geißel aufgehalten wird. Die Dunkle Fürstin dankt Euch für Eure Bemühungen und möchte Euch zur Belohnung ein Geschenk machen.\n\nWir wissen zwar nicht, wie groß der Einfluss der Geißel in den Hügeln ist, aber wir werden bestimmt schon bald einiges über ihre Pläne herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6522] = { id = 6522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", sourceObjective = "Bringt die kleine Rolle zu Bragor Blutfaust im Königsviertel von Unterstadt.", progress = "Worüber wollt Ihr mit mir sprechen, {name}? Es muss wohl wichtig für Euch sein, wenn Ihr mich ständig belästigt.", completion = "Ich erkenne die Insignien auf dieser Rolle, {name}. Ihr habt dies bei der Greisin gefunden, die über den Kral von Razorfen herrscht? Interessant.\n\nDie Geißel scheint sich also offenbar nicht mit einem Kontinent zufrieden zu geben. Dieser Botschafter Malcin - der diese Notiz geschrieben hat - ist einer der von der Geißel verseucht wurde. Er war ein menschlicher Diplomat des Königreichs Lordaeron, bevor sich alles ... verändert hat.\n\nFalls die Geißel versucht, in Kalimdor Fuß zu fassen, liegt es an uns zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[6523] = { id = 6523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützt Kaya", description = "Habt Dank für meine Rettung! Wir müssen schnell fort von hier, ehe man bemerkt, dass ich frei bin. Bitte begleitet mich zum Camp Aparaje. Von dort aus kenne ich den Weg.\n\nMein Vater Makaba Flachhuf wird unbedingt wissen wollen, dass ich in Sicherheit bin.", sourceObjective = "Begleitet Kaya Flachhuf zum Camp Aparaje und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", completion = "Kaya lebt! Ich habe Euch für ihre Rettung zu danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6541] = { id = 6541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Kadrak", description = "Seid Ihr jemals im Norden des Eschentals gewesen? Die Horde hat dort vor Kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Eschentalkampagne und kann Euch weitere Befehle geben.", sourceObjective = "Meldet Euch im Wachturm im Nördlichen Brachlands bei Kadrak.", completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", sourceObjectiveStatus = "unverified-source-field" }
quests[6542] = { id = 6542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Kadrak", description = "Seid Ihr jemals im Eschental nördlich von hier gewesen? Die Horde hat dort vor Kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Eschentalkampagne und kann Euch weitere Befehle geben.", sourceObjective = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", sourceObjectiveStatus = "unverified-source-field" }
quests[6543] = { id = 6543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berichte des Kriegshymnenklans", description = "Ich habe kürzlich ein paar Späher ins Eschental entsandt und brauche jetzt einen Kurier, der ihnen neue Befehle übermittelt und mir einen Bericht über deren Entdeckungen bringt.\n\nEuer erster Halt sollte der Außenposten von Zoram'gar an der Küste Richtung Westen sein. Dort solltet Ihr den ersten Läufer finden. Ihr müsst weiterhin beim Splitterholzposten im Norden und an der Straße nach Osten, die nach Azshara führt, Halt machen. Dort findet Ihr einen Späher und eine Vorhut.\n\nErstattet allen Bericht und lasst Euch von ihnen über ihre Entdeckungen informieren.", sourceObjective = "Öffnet die gebündelten Berichte. Bringt die Berichte des Kriegshymnenklans dem Späher des Kriegshymnenklans, dem Läufer des Kriegshymnenklans und der Vorhut des Kriegshymnenklans. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.", progress = "Beeilt Euch, {name}. Sie müssen die Berichte erhalten, es ist wichtig.", completion = "Wie ich sehe, kann ich auf Euch zählen. Diese Neuigkeiten sind unerlässlich für unsere Pläne, unsere Position in Ashenvale zu festigen. Jetzt können wir unseren nächsten Schritt planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6544] = { id = 6544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toreks Angriff", description = "He! {class}! Kommt mal her!\n\nMeine Räuber und ich wollten gerade den Außenposten der Silberschwingen im Westen angreifen. Unser Ziel ist die dortige Anführerin, Duriel Mondfeuer. Späher berichten, dass der Außenposten durch Schildwachen und Krieger stark verteidigt wird. Das wird ein ruhmreicher Kampf!\n\nWollt Ihr an dem Ruhm teilhaben und uns helfen, {name}? Falls ja, könnt Ihr meinem Vorgesetzten Ertog Zornhauer im Splitterholzposten später davon berichten.\n\nWas meint Ihr? Seid Ihr dabei?", sourceObjective = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silberschwingen und Duriel Mondfeuer. Erstattet dann Ertog Zornhauer im Splitterholzposten Bericht.", completion = "Toreks Angriff war also erfolgreich! Gut gemacht, {name}. Nachtelfen sind angemessene Feinde. Ein bisschen mager zwar, aber stark und wild! Die Schlacht war bestimmt eine Augenweide...\n\nUnd ich hoffe, Ihr habt Euch ein paar Narben verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[6545] = { id = 6545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktualisierter Bericht des Läufers des Kriegshymnenklans", progress = "Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.\n\nIhr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, {name}. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.\n\nWenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten.", completion = "So, mein neuer Bericht wird Kadrak alles erklären. Ihr müsst dies so schnell wie möglich zu ihm zurückbringen." }
quests[6546] = { id = 6546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktualisierter Bericht der Vorhut des Kriegshymnenklans", sourceObjective = "Auf diesem Weg lauern viele Gefahren, {name}. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können... seid auf das gefasst, was vor Euch liegt, {name}.", progress = "Auf diesem Weg lauern viele Gefahren, {name}. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können ... seid auf das gefasst, was vor Euch liegt, {name}.", completion = "Bringt Kadrak meinen neuen Bericht. Schnellstens, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6547] = { id = 6547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktualisierter Bericht des Spähers des Kriegshymnenklans", progress = "Haltet die Augen offen, {race}. Oftmals verstecken sich Elfen in den Schatten...\n\nWir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.\n\nIch nehme an, Ihr habt neue Befehle von Kadrak für mich?", completion = "Berichtet Kadrak, wie erfolgreich wir die Nachtelfen hier aufgehalten haben. Unsere Pläne laufen gut." }
quests[6548] = { id = 6548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt mein Dorf", description = "Der Grimmtotemklan hat mein Dorf überfallen und fast alle getötet. Ich habe so viele ich konnte niedergestreckt, bin aber nur um Haaresbreite lebend entkommen.\n\nJetzt wünsche ich mir nichts mehr, als noch mehr von ihnen tot zu sehen, {name}. Ihr findet sie gleich westlich von hier.", sourceObjective = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", progress = "Habt Ihr sie schon getötet?", completion = "Ich danke Euch, {name}... aber ich werde niemals vergessen, was die Grimmtotem meinem Dorf angetan haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[6561] = { id = 6561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in der Tiefschwarzen Grotte", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Bashana in Donnerfels seinen Kopf, {name}.", sourceObjective = "Bringt den Kopf von Zwielichtfürst Kelris zu Bashana Runentotem in Donnerfels.", progress = "Möge die Erdenmutter mit Euch sein, {name}.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, {name}.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der alten Götter huldigte. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6562] = { id = 6562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in der Tiefe", description = "Je'neu Sancrea braucht Hilfe. Er wartet am Eingang zur Tiefschwarzen Grotte im Eschental. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, {name}. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird.", sourceObjective = "Sprecht im Eschental mit Je'neu Sancrea.", completion = "Tsunaman schickt Euch? Ausgezeichnet. Dann haben wir einiges zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6563] = { id = 6563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz von Aku'mai", description = "Im Eingangsbereich des Tunnels der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.\n\nWerdet Ihr mir helfen, {name}? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.", sourceObjective = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea im Eschental.", progress = "Wie läuft Eure Suche nach den Kristallen, {name}? Habt Ihr die Naga beim Abbau der Steine gesehen? Ich bete zu meinen Vorfahren, dass wir den Grund dafür herausfinden, warum sie diese Dinge sammeln.", completion = "Gut gemacht, {name}. Das sind die Kristalle, von denen ich sprach. Faszinierend...\n\nIch kann die Macht in ihnen spüren. Die Geister des Wassers hängen an ihnen. Was immer die Naga mit ihnen vorhatten... tja, seien wir nur froh, dass sie nicht mehr in ihren Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6564] = { id = 6564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zu den Alten Göttern", description = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:\n\n\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.\n\nIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"", sourceObjective = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea im Eschental.", progress = "Ja, {name}? Was ist Euer Begehr? Ich muss noch so viel über die Kristalle lernen, die die Naga zusammentragen.", completion = "Das ist in der Tat interessant. Ich bin froh, dass Ihr mich davon in Kenntnis gesetzt habt.\n\nJetzt können wir unseren Problemen auch einen Namen geben... Lorgus Jett.", sourceObjectiveStatus = "unverified-source-field" }
quests[6565] = { id = 6565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zu den Alten Göttern", description = "Dieser Anhänger des Schattenhammerklans darf seinen Plan nicht in die Tat umsetzen. Die Schattenhammerkultisten verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, {name}. Ich kann mich leider nicht selbst darum kümmern... ich bin zu schwach.\n\nGeht zur Tiefschwarzen Grotte, findet ihn und tötet ihn. Kehrt hierher zu mir zurück.", sourceObjective = "Tötet Lorgus Jett.", completion = "Sehr gut! Danke, {name}. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6566] = { id = 6566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was der Wind erzählt", description = "Schön, Euch wiederzusehen, {name}. Der Wind führt Kunde aus den Östlichen Königreichen mit sich.\n\nSetzt Euch und lauscht.", sourceObjective = "Hört Thrall zu.", progress = "Geduld, {name}. Passt gut auf!", completion = "Seid Ihr bereit, diese Aufgabe anzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[6567] = { id = 6567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Champion der Horde", description = "Rexxar, einer meiner treuesten Helden, hat einen Weg in den Hort des Drachen gefunden. Leider ist er mit unserer Expedition in die Scherbenwelt aufgebrochen.\n\nEr hat jedoch zuvor seinem Freund Rokaro in Schattenflucht die Einzelheiten mitgeteilt. Sucht nach ihm!", sourceObjective = "Sucht in Schattenflucht in Desolace nach Rokaro.", completion = "Es gibt nur einen Weg in den Hort des Großdrachen, {race}.\n\nWisst Ihr, nur die Stärksten des schwarzen Drachenschwarms dürfen den Hort der Brutmutter betreten. Es müssen viele Prüfungen überwunden werden und der Schlüssel, mit dem man hineingelangt, wurde von General Drakkisath persönlich zeremoniell verzaubert!\n\nDa Ihr nicht zu den schwarzen Großdrachen gehört, werdet Ihr wohl auf einige Schwierigkeiten stoßen, wenn Ihr Einlass verlangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6568] = { id = 6568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterin der Illusionen", description = "Illusion und Täuschung. So werdet Ihr es schaffen, den schwarzen Drachenschwarm zu überlisten und zu erlangen, was Ihr sucht.\n\nAuch wenn ich Euch in der Kunst der Täuschung unterrichten könnte, werdet Ihr die Hilfe eines Meistern benötigen.\n\nIch kenne jemanden, der Euch dabei helfen kann. In den Westlichen Pestländern findet Ihr Myranda die Vettel, eine Meisterin der Illusionen aus Lordaeron. Sie hat uns in der Vergangenheit bereits geholfen. Wenn Ihr sie davon überzeugen könnt, dass Eure Sache es wert ist, wird sie Euch vielleicht unterstützen.\n\nBringt diese Nachricht zu ihr.", sourceObjective = "Überbringt Myranda der Vettel in den Westlichen Pestländern Rokaros Brief.", progress = "In diesem Teil Lordaerons sieht man nur selten einen aus der Horde. Was habt Ihr für Myranda?", completion = "<Myranda hält die Notiz, schweigt eine Weile, dann lächelt sie.>\n\nWie geht es ihm? Rexxar, meine ich. Oh, bitte, schaut nicht so überrascht drein. Der Brief besteht absichtlich nur aus einem leeren Blatt. Er trägt die Absichten und Gedanken des Schreibers. Angesichts des Inhalts ist es kein Wunder, dass Rexxar so verfahren ist. Stellt Euch vor, man hätte Euch gefangen oder getötet und diese Informationen entdeckt!\n\nAch, wie dem auch sei! Myranda wird Euch helfen, {race}. Ich schulde dem Kriegshäuptling noch einen oder zwei Gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6569] = { id = 6569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculus-Illusionen", description = "Ihr möchtet also einer vom schwarzen Drachenschwarm werden, was, {race}?\n\nDie Erschaffung einer Illusion, wie Ihr sie wünscht, ist eine Kleinigkeit, aber die für den Zauber erforderlichen Komponenten sind ziemlich schwierig zu beschaffen. Der Kriegshäuptling hat Euch mit dieser Mission betraut, also muss Myranda wohl annehmen, dass Ihr fähig dazu seid.\n\nReist zur oberen Zitadelle der Schwarzfelsspitze und tötet genug Mitglieder der schwarzen Drachenbrut, um eine Eurer Taschen mit deren Augen zu füllen.\n\nKehrt zu Myranda zurück, wenn Ihr genügend von dem Reagenz gesammelt habt.", sourceObjective = "Reist zur Schwarzfelsspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.", progress = "Die Augen derer, die wir verkörpern möchten, sind die wichtigste Zutat für jede Illusion, {name}.", completion = "Lasst Myranda mal sehen, {race}.\n\nAh ja, ausgezeichnet.\n\nAus diesen Reagenzien wird Myranda ein Medaillon für Euch fertigen, mit dem Ihr eine Illusion erzeugen könnt, die den Torhüter des schwarzen Drachenschwarms täuschen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[6570] = { id = 6570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschenschwinge", description = "Ich habe dieses Medaillon mit der Magie versehen, die notwendig ist, um eine Illusion zu erschaffen und sie innerhalb der Einfriedung des Höhlenbaus von Aschenschwinge aufrechtzuerhalten.\n\nAschenschwinge ist ein uralter Drache, ein alter Torwächter Nefarians, der die schwere Bürde auf seinen Schultern trägt, jene der Drachenbrut auf die Probe zu stellen, die in den Rang einer Elitewache Onyxias aufsteigen wollen.\n\nReist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr dort seid, legt Ihr das Amulett an und folgt Eurem Schicksal, wo immer es Euch auch hinführen mag!", sourceObjective = "Reist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.\n\nBereitgestellter Gegenstand:", completion = "Haben wir nur noch so wenige Soldaten, dass Nefarian mir schon Welpen schickt? Du wirst meine Prüfungen nie bestehen, Brutling.", sourceObjectiveStatus = "unverified-source-field" }
quests[6571] = { id = 6571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub des Kriegshymnenklans", description = "Uns hier im Holzfällerlager des Kriegshymnenklans gehen langsam einige Dinge aus!\n\nUnsere Lieferung Sägeblätter liegt bei Pixel im Splitterholzposten. Jemand muss auch nach Beutebucht reisen, um eine Kiste mit Äxten bei Werftmeister Lozgil abzuholen.\n\nBei unserer Öl- und Seillieferung sieht es jedoch schon schwieriger aus. Die Furbolgs haben die Seile geraubt und die Satyrn haben das Öl abgefangen und nutzen es jetzt für abscheuliche Rituale in der Nachtflucht, Satyrnaar und Xavian!\n\nIch komme in große Schwierigkeiten, wenn ich die Sachen nicht bald ausliefere... könnt Ihr mir helfen?", sourceObjective = "Tragt den Nachschub des Kriegshymnenklans zusammen: Sägeblätter des Kriegshymnenklans, ein Holzfällerseil, Öl des Kriegshymnenklans und die Axtlieferung des Kriegshymnenklans für Locke Okarr im Splitterholzposten.", progress = "Hoffentlich kommt Ihr mit dem Nachschub durch!", completion = "Exzellent, {name}. Ihr habt mir eine Menge Arbeit erspart!\n\nAber glaubt nicht, dass ich mich nicht erkenntlich zeige!", sourceObjectiveStatus = "unverified-source-field" }
quests[6581] = { id = 6581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägeblätter des Kriegshymnenklans", progress = "Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...\n\nAber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!\n\nWas ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.\n\nWenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?", completion = "Das ist perfekt - genau das, was ich wollte! Und hier habt Ihr die Lieferung." }
quests[6582] = { id = 6582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Schädel, Seher", description = "Wir sind Kinder von Todesschwinge, Welpe. Wir müssen die Herrschaft über die niederen Aspekte durchsetzen.\n\nWenn Ihr wirklich eines Aufstiegs würdig seid, werden die Geringeren des Drachenschwarms vor Euch niedersinken.\n\nFindet deren Champions und vernichtet sie im Namen unseres Vaters!\n\nBegebt Euch nach Winterquell und spürt den mächtigen Blaudrachen Seher auf. Zerschmettert ihn und alle anderen des blauen Drachenschwarms, die sich Euch in den Weg stellen. Entreißt ihm seinen Schädel und bringt ihn mir.", sourceObjective = "Ihr müsst Seher, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Seher in Winterquell zu finden ist.", progress = "<Aschenschwinge faucht.>", completion = "Eine von etlichen Prüfungen überssstanden...", sourceObjectiveStatus = "unverified-source-field" }
quests[6583] = { id = 6583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Schädel, Somnus", description = "Genau wie unser Vater die Aspekte zerschmettert, müssen wir danach trachten, Chaos und Zerstörung unter ihren Kindern anzurichten.\n\nIhr müsst Eure Leistungsfähigkeit im Kampf gegen die schlaflosen Träumer auf die Probe stellen: die Kinder des Gründrachenschwarms.\n\nBegebt Euch zu den Sümpfen des Elends und spürt Somnus auf, den Drachenchampion des Gründrachenschwarms. Lasst Eurem Hass freien Lauf und bezwingt das Insekt...Kommt mit seinem Schädel zu mir zurück...", sourceObjective = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.", progress = "Kommt erst wieder, wenn Ihr im Blut unserer Feinde gebadet und Euch an ihrem Leiden gelabt habt.", completion = "Eine weitere bestanden...", sourceObjectiveStatus = "unverified-source-field" }
quests[6584] = { id = 6584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Schädel, Chronalis", description = "Die Zeitbehüter, Kinder Nozdormusss - Lord der Jahrhunderte...\n\nEs sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der schwarze Drachenschwarm interessiert ist: Chronalisss, der Zeitverschieber, bevorzugter Drachling Nozdormusss.\n\nBesssiegt diesssen Champion, denn das wäre ein Schlag, der sssogar den stoischen Sand der Zzzeit erschüttern würde. Kehrt mit seinem Schädel zu mir zzzurück.", sourceObjective = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.", progress = "Ironischerweissse ist hier die Zzzeit entscheidend, Welpe.", completion = "Der am meisssten Verhasssssste fehlt Euch noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[6585] = { id = 6585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Schädel, Axtroz", description = "Es war in den Bergen von Grim Batol, wo unser Vater gegen die vereinte Macht der Aspekte wütete. Die feige Tat der Verräterin Alexstrasza verschaffte den übrigen Aspekten genug Zeit, um dem Zorn des Vaters zu entkommen.\n\nWasss für ein schändlicher Akt...\n\nDer rote Drachenschwarm bewacht heute Grim Batol und ihr Leutnant Axtroz muss vernichtet werden. Bringt mir Axtroz' Schädel. Für den Vater, Welpe!", sourceObjective = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.", progress = "Veränderungen... Ich spüre sie schon in Euch, Welpe. Besteht diese Prüfung, dann wartet nur noch eine Zeremonie auf Euch.", completion = "Ich habe mich in Eurem Engagement getäuscht, Welpe. Ihr wart beharrlich, habt unsere Feinde bezwungen und unserem Klan Ehre gemacht.\n\nJetzt muss ich die Schädel für Euren Aufstieg vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[6601] = { id = 6601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg...", description = "Ein Medaillon, aus den Schädeln Eurer Feinde gefertigt. Ihr kennt dieses Medaillon, nicht wahr? Zweifellos habt Ihr gesehen, wie Eure Ältesten es trugen.\n\nNehmt es, Welpe. Begebt Euch zur Spitze zurück und zeigt es General Drakkisath. Der General wird das Medaillon mit der letzten Verzauberung versehen und das Schmuckstück auf Euren Geist abstimmen.\n\nIhr werdet das fertige Medaillon als Ehrenabzeichen tragen, als Symbol für Euren Aufstieg in unsere am höchsten geschätzten Reihen: Wächter der Brutmutter.\n\nGeht!", sourceObjective = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Schwarzfelsspitze nicht funktioniert. Vielleicht solltet Ihr Rokaro aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.", progress = "Keine Panik, {name}!", completion = "Das ist reines Drachengeschwätz, {name} - viel heiße Luft und keine greifbaren Informationen. Was soll man von ihnen auch anderes erwarten als aufgeblasenes, aggressives Verhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[6602] = { id = 6602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des schwarzen Großdrachenhelden", description = "Ihr werdet dem General einen Besuch abstatten, jawohl, aber nicht als einer des schwarzen Drachenschwarms.\n\nWisst Ihr, Zeremonie ist für den schwarzen Drachenschwarm nur ein anderer Begriff für Aderlass.\n\nDas ruhende Amulett benötigt nur das Blut des Generals, um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen.\n\nKehrt zur Schwarzfelsspitze zurück und vernichtet Drakkisath. Bringt sein Blut hierher zurück, dann aktiviere ich den Schlüssel zu Onyxias Hort.", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rokaro.", progress = "Man darf Drakkisath nicht unterschätzen, {name}. Er hat den Tod von Tausenden auf dem Gewissen.", completion = "<Rexxar grinst.>\n\nDie Geschichte Eurer Heldentaten wird man sich noch jahrelang erzählen, {name}. Das Drachenfeueramulett ist der Schlüssel zu Onyxias Hort. Sammelt Eure Streitmacht und erobert ihn im Namen der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[6603] = { id = 6603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probleme in Winterquell!", description = "In Winterquell gibt es Probleme!\n\nSicher, ich habe einige Zeit da draußen in der Wildnis zugebracht und weiß um diese Dinge... Es macht mich immer ganz stolz, das zu sagen. Für mich waren die Stunden, die ich dort draußen in den Hügeln verbrachte, etwas ganz Besonderes. Es hilft einem, blitzschnelle Reflexe zu entwickeln, einen kühlen Kopf und ein wachsames Auge zu bewahren...\n\nMan braucht Urteilsvermögen, Grips und Reife, um die Wildnis so schätzen zu können, wie ich es tue.\n\nAlso, worüber wollte ich eigentlich sprechen?\n\nAch ja, Probleme. Sprecht mit Donova Schneeweh bei den Thermalquellen. Sie wird Euch mehr sagen können.", sourceObjective = "Findet Donova Schneeweh bei den Thermalquellen in Winterquell.", completion = "Hallo, Ihr da! Meggi hat Euch also schon von den Problemen erzählt, auf die ich hier gestoßen bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[6604] = { id = 6604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Ist Euch das verlassene Lager südlich von hier aufgefallen? Es scheint, als wären die Wildekin verrückt geworden und haben so gut wie alles zerstört, was sie finden konnten!\n\nIch hab Gerüchte gehört, wonach einer der Überlebenden des Angriffs sich in Sternfall aufhalten soll, das liegt westlich von hier. Ich bin neugierig, was wohl geschehen sein mag...Ihr nicht auch?", sourceObjective = "Sprecht mit Jaron Steinschleifer in Sternfall.", completion = "Aye, was kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[6605] = { id = 6605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Person", description = "Ich bin gerade erst vom Teufelswald zurückgekehrt, {name}. Unterwegs habe ich im Blutgiftposten Halt gemacht und eine wirklich eigenartige Bekanntschaft gemacht... Sie schien ganz besessen von einer Sache gewesen zu sein, und ich könnte Euch wohl erzählen, um was es sich handelt, aber ich denke, das sollte sie Euch selbst erklären.\n\nGeht zum Blutgiftposten im Westen des Teufelswalds und fragt nach Winna Hazzard, falls Ihr Interesse habt.\n\nWer weiß, vielleicht braucht sie ja Eure Hilfe...", sourceObjective = "Sprecht im Teufelswald mit Winna Hazzard.", completion = "Ah, {class}. Also gibt es wohl doch noch Hoffnung. Seid Ihr hier, um mir zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[6606] = { id = 6606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen Glück", description = "Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in der Ewigen Warte auf. Meinen bekommt Ihr nämlich nicht!", sourceObjective = "Sprecht in der Ewigen Warte mit Hexendoktorin Mau'ari.", sourceObjectiveStatus = "unverified-source-field" }
quests[6607] = { id = 6607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Extremangler", description = "Ich kann nicht behaupten, dass ich gern angele. Ich glaub, ich mach das jetzt seit gut 20 oder 30 Jahren.\n\nEs gibt wohl viele Gründe, die einen dazu treiben, etwas zu tun.\n\nIch will damit jetzt nicht sagen, dass Ihr 30 Jahre lang angeln oder jeden einzelnen Fisch im Meer fangen müsst, um ein Meisterangler zu werden. Man muss einfach nur entschlossen sein - entschlossen genug, um stundenlang auf dem Hintern zu sitzen und nichts zu tun.\n\nIch sag Euch was: Fangt mir ein paar seltene Fische, dann bring ich Euch das eine oder andere bei. Hier habt Ihr eine Liste:", sourceObjective = "Nat Pagle möchte, dass Ihr folgende Fische fangt:\n\nNebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.\n\nEinen Sar'therisbarsch vom Sar'therisstrand in Desolace.\n\nFeralas-Ahi aus dem Verdantis in Feralas.\n\nBlauwimpel von der Ungezähmten Küste im Schlingendorntal.\n\nKehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!", progress = "Na, hat heute schon einer angebissen?", completion = "Also das nenn ich einen tollen Fang!\n\nKommt hier rüber, dann zeig ich Euch, wie man die Leinen auswirft.", sourceObjectiveStatus = "unverified-source-field" }
quests[6608] = { id = 6608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr zu gut", description = "Lumak können {name} nix mehr beibringen. Ihr zu gut! Finden Freund von Lumak, Nat Pagle. Er sein Mensch, aber nix Futter! Ist Freund von Lumak! Nat Euch zeigen, wie besserer angeln.\n\nIhr finden Nat in den Düstermarschen, Süden von Thermoro-odersoähnlich. Nat bestimmt angeln. Ihr jetzt gehen!", sourceObjective = "Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht.", completion = "Klar, Ihr müsst ein Freund von Lumak sein.\n\nAngeln? Ich kann Euch alles übers Angeln erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6609] = { id = 6609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab nix mehr!", description = "Ich bin ein Zwerg, zum Donnerwetter nochmal, <Jungchen/junge Dame>! Ich hab mit Angeln nichts am Hut! Ich meine, seht mich doch mal an! Ich bestehe praktisch aus Stein.\n\nIch hab nichts mehr - Ihr habt mich ausgelaugt. Ich hab Euch alles beigebracht, was ich weiß, flipflop!\n\nKapiert Ihr's nicht? Ah, gut. Ich hab in Kalimdor einen alten Freund, der Euch weiterhelfen kann. Heißt Nat Pagle, guter Junge. Findet ihn auf den Inseln südlich von Theramore. Jetzt verfatzt Euch!", sourceObjective = "Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!", completion = "Ich hab auf meiner Insel immer Platz für Besucher... Würde ich sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6610] = { id = 6610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelette Surprise", description = "Schon mal von einem Muschelette gehört? Natürlich nicht! Das ist mein neuestes kulinarisches Meisterwerk. Oh, {name}, mir läuft das Wasser im Mund zusammen, wenn ich nur an ein Muschelette denke.\n\nLeider habe ich nichts mehr hier, um eins zu machen! Wie wär's mit einem Handel? Ihr besorgt die Zutaten für ein Muschelette und ich bring Euch die Feinheiten der exotischen Küche bei und leg' sogar noch ein paar Muschelettes drauf! Abgemacht?\n\nUnd das brauche ich dafür:", sourceObjective = "Dirge Schnetzelhack möchte, dass Ihr folgende Dinge besorgt:\n\n10 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.\n\n10 Stück scharfes Muschelfleisch. Das findet Ihr natürlich in Muscheln!\n\n20 Stück feiner alter Cheddar. Begebt Euch zu einer Käserei!\n\nSammelt all diese Gegenstände und kehrt dann zu Dirge zurück.", progress = "Meine Gelüste bringen mich noch mal um! Schnell, {name}, bevor ich den Kitt aus den Fenstern futtere.", completion = "Freut Euch auf ein ganz besonderes Vergnügen, {name}. Seht zu und lernt!", sourceObjectiveStatus = "unverified-source-field" }
quests[6611] = { id = 6611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab mit Euch nach Gadgetzan!", description = "Erwartet Ihr etwa, dass Zamja Euch noch irgendwas beibringt? Ihr kennt schon alle von Zamjas Küchentricks und verlangt immer noch nach mehr!\n\nZamja kann nicht helfen. <Fetter/Fette:r> {race} muss nach Gadgetzan gehen. Dort findet Ihr einen kleinen Goblin namens Dirge - er wird Euch helfen, Dickerchen.\n\nWenn Ihr dann ein richtiger Sternekoch seid, kommt Ihr zurück und gebt Zamja Unterricht, okay? Und jetzt geht!", sourceObjective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere.", completion = "<Dirge spuckt ein paar Fetzen der Ledersandale aus.>\n\nPfui...\n\n<Dirge hustet laut.>\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[6612] = { id = 6612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kenne einen Typen...", description = "Das seh ich doch an Eurem Kochlöffel, dass Ihr wisst, was Ihr tut. Leider kann ich Euch nichts beibringen.\n\nGlück für Euch, ich kenn da einen Typen. Er ist ein Goblin und wahrscheinlich der beste Koch von ganz Kalimdor.\n\nHajo, und jetzt die schlechte Nachricht, <Jungchen/Mädel> - Ihr müsst nach Kalimdor reisen. Geht nach Gadgetzan und sucht nach Dirge Schnetzelhack. Er wird's Euch beibiegen.", sourceObjective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere.", completion = "<Dirge spuckt Leder aus.>\n\nPfft...\n\n<Dirge hustet laut.>\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6621] = { id = 6621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Fäulnisklauen", description = "Meine Forschungen haben sich bezahlt gemacht.\n\nIch glaube, dass eine Machtdemonstration die Angriffslust der Furbolgs verringern wird.\n\nNehmt dieses Banner, geht ein paar Schritte in Richtung Nordosten und platziert es auf ihrem Totemhügel. Sie werden versuchen, das Banner zu zerstören, aber Ihr müsst Eure Stellung halten, bis Häuptling Murgut auftaucht, um das Gesicht seines Stammes zu wahren. Bringt mir das Totem, das er trägt.\n\nVersammelt Eure Verbündeten, {name}. Dies ist keine Aufgabe, die <ein einzelner/eine einzelne:c> {class} bewältigen kann.", sourceObjective = "Platziert Senanis Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Senani in der Silberwindzuflucht.", progress = "Habt Ihr Häuptling Murgut besiegt, {name}? Habt Ihr das Fäulnisklauentotem?", completion = "Gute Arbeit, {name}. Indem wir die Fäulnisklauen herausgefordert und ihren Anführer besiegt haben, haben wir ihnen eine nachdrückliche Warnung erteilt:\n\nMan darf die Horde nicht unterschätzen.\n\nIch glaube, dass uns dieser Stamm für lange Zeit keine Scherereien mehr machen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[6622] = { id = 6622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triage", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Horde.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die Leichtverletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nVerbände werden gestellt.\n\nViel Glück, Doktor.", sourceObjective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", completion = "Doktor {name}, willkommen bei den Traumachirurgen der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[6623] = { id = 6623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumachirurg der Horde", description = "Doktor {name}, nehme ich an. Es ist mir eine Freude, Euch wiederzusehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Doktor Gregory Victor, Chefarzt der Traumachirurgen der Horde, hat Euch persönlich angefordert, damit Ihr Euch ihm in Hammerfall anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gregory Victor studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen!", sourceObjective = "Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt.", completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[6624] = { id = 6624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triage", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Allianz.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die Leichtverletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nViel Glück, Doktor.", sourceObjective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", completion = "Doktor {name}, willkommen bei den Traumachirurgen der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[6625] = { id = 6625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumachirurg der Allianz", description = "Doktor {name}, nehme ich an. Es ist mir eine Freude, Euch zu sehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Gustav van Howzen, Chefarzt der Traumachirurgen der Allianz, hat Euch persönlich angefordert, damit Ihr Euch ihm in Theramore anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gustav van Howzen studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen, Doktor!", sourceObjective = "Reist nach Theramore in die Düstermarschen und sprecht mit Doktor Gustav van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt.", completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[6626] = { id = 6626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hort des Bösen", description = "Die Verlassenen geben ihre... Krankheit... nicht weiter, soweit ich das sehe. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Ich glaube langsam, dass er der Geißel angehört.\n\nUm ihn mache ich mir allerdings momentan keine Gedanken, sondern um die wachsende Schar um ihn herum. Tag für Tag kriechen sie aus den Schatten und betteln ihn nahezu um mehr Macht an.\n\nIch bin nicht stark genug, um sie allein zu bekämpfen, {name}. Was meint Ihr? Hättet Ihr Lust, auf die Jagd zu gehen?", sourceObjective = "Tötet 8 Schlachtwachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Mondsang nahe dem Eingang zu den Hügeln der Klingenhauer zurück.", progress = "Wie läuft die Jagd, {name}? Wenn ich nur dieses kleine Beispiel der Macht dieses Diplomaten hier sehe, zweifle ich nicht mehr daran, dass die Geißel eine der größten Bedrohungen ist, die die Welt je gesehen hat.", completion = "Danke, {name}! Die Arbeit, die Ihr geleistet habt, wird eine große Hilfe sein, da bin ich mir sicher.\n\nIch werde meine Studien über diesen Diplomaten und den Rest der Stacheleber hier fortsetzen. Wenn Ihr auf größere Abenteuer aus seid, würde ich ein paar Freunde zusammentrommeln und in die Höhle da drüben gehen, die wie ein riesiges Ebermaul aussieht. Ich bin sicher, dass Ihr dort drinnen noch auf viel größere Herausforderungen stoßen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[6627] = { id = 6627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Ihr habt mir das Buch gebracht, und jetzt ist es an der Zeit für Eure Befragung. Seid Ihr bereit?\n\nZeit spielt keine Rolle, {class}, also fühlt Euch nicht unter Druck gesetzt. Ihr könnt Euch mit der Antwort so viel Zeit lassen, wie Ihr möchtet.", sourceObjective = "Beantwortet Braug Dämmergeists Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.", progress = "Das Leben ist voller Fragen, {class}. Ihr werdet sie niemals alle beantworten können, aber mit der Zeit und durch Studien werdet Ihr Euch bestimmt weiteres Wissen aneignen.", completion = "Gut gemacht, {class}. Ihr habt den Text studiert, wie ich Euch gebeten habe, und jetzt habt Ihr eine weitere unserer Prüfungen bestanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6628] = { id = 6628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Die Zeit ist also wieder einmal gegen uns. Für einen Studenten der Lehre habt Ihr große Hartnäckigkeit bewiesen, indem Ihr meine Aufgabe erledigt habt.\n\nUnd deshalb werde ich Euch eine Frage anbieten. Wenn Ihr bereit seid, sprecht mich wieder an, und lasst Euch so viel Zeit, wie Ihr braucht, {name} - es besteht keine Notwendigkeit, schnell zu antworten.", sourceObjective = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Unterstadt sein, wenn Ihr bereit seid.", progress = "Es gibt nur eine Regel, die Ihr meiner Meinung nach kennen solltet, wenn Ihr in dieser Welt überleben wollt: Je mehr Ihr wisst, desto mehr werdet Ihr sehen.\n\nWenn Ihr studiert, wenn Ihr beobachtet, beginnt Ihr Dinge in der Welt zu sehen, die kein anderer {race} sehen kann.", completion = "Gut gemacht, {name}. Ich hatte meine Zweifel, ob Ihr den Text studieren würdet, den ich Euch gebeten habe zu holen, aber Ihr habt richtig geantwortet.", sourceObjectiveStatus = "unverified-source-field" }
quests[6629] = { id = 6629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Grundig Finsterwolke", description = "{name}, Ihr habt gute Arbeit geleistet, indem Ihr Grimmtotem tötetet. Grundig Finsterwolke und seine persönliche Schlägerbande sind bei weitem die Schlimmsten von allen, wenn Ihr Euch traut. Er war einer derjenigen, die den brutalen Angriff auf mein Dorf anführten.\n\nIhr findet ihn im Grimmtotemposten ein Stück weiter den Weg nach Westen hinauf. Tötet ihn, dann werde ich Euch immer dankbar sein.", sourceObjective = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück.", progress = "Habt Ihr Grundig Finsterwolke und seine persönliche Schlägerbande getötet?", completion = "Grundig Finsterwolke ist tot! {name}, ich werde immer für das dankbar sein, was Ihr heute hier geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6641] = { id = 6641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsha die Peitscherin", description = "Vorsha die Peitscherin... die satanische Hydra, die die Meere durchstreift...\n\nSie hat unseren Außenposten angegriffen, völlig ohne Grund, und dabei alles verheert, was auf ihrem Weg lag.\n\nAber ich bin bereit, {name}. Ich bin bereit, die Hydra zu besiegen und den Angriffen auf Zoram'gar ein Ende zu setzen.\n\nDie Naga verehren die tückische Natur dieser Bestie mit einer Kohlenpfanne, die auf einer Insel gleich vor der Küste immer am Brennen gehalten wird. Ich denke, dass Vorsha erzürnt auftauchen wird, wenn wir sie löschen.\n\nWir werden jedoch Hilfe brauchen, also solltet Ihr ein paar starke Verbündete mitbringen.", sourceObjective = "Bezwingt Vorsha die Peitscherin.", completion = "Ich habe schon viele Nagaangriffe miterlebt, seit ich hier bin. Es beruhigt mich, dass Vorsha nicht mehr ihr Unwesen treibt.\n\nWir stehen in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6642] = { id = 6642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Bruderschaft, Dunkeleisenerz", progress = "Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.\n\nFür 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen." }
quests[6643] = { id = 6643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Bruderschaft, Feuerkern", progress = "Wehe denen, die im Geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.\n\nViele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.\n\nBietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen." }
quests[6644] = { id = 6644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Bruderschaft, Lavakern", progress = "Die Thoriumbruderschaft versteht Eure Notlage, {race}. Deshalb haben wir Lokthos zu einem Handel ermächtigt.\n\nBietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen." }
quests[6645] = { id = 6645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Bruderschaft, Kernleder", progress = "Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.\n\nBietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen." }
quests[6646] = { id = 6646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Bruderschaft, Blut des Berges", progress = "Die Tränen des Feuerlords sind wahrlich ein seltener Fund.\n\nBietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen." }
quests[6661] = { id = 6661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenbahn-Ratten-Razzia", description = "Haltet ein, Taugenichts. Arrrr... Sucht Ihr Arbeit? Wir ha'm hier ein echtes Rattenproblem und nicht genügend Leute auf dem Hüttendeck.\n\nWas sagt Ihr? Ihr müsst nur diese Rattenfängerflöte nehmen und dem Ungeziefer ein Liedchen vorspielen. Die folgen Euch dann bis ans Ende der Welt!\n\nFangt mir fünf von den kleinen Mistviechern und bringt sie mir. Ich brauch sie lebendig.\n\nArrrrr...", sourceObjective = "Fangt mithilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty.", progress = "Harrr... Deckschrubber, was dauert das so lange?", completion = "Die sind ausgezeichnet, Kumpel. Mein Bruder braucht sie quietschlebendig und zappelig, sonst verderben sie... Ihr wollt doch wohl keinen verdorbenen Rattenkebab probieren, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[6662] = { id = 6662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Bruder Nipsy...", description = "Mein Bruder Nipsy hat 'n Rattengeschäft auf der anderen Seite der Tiefenbahn. Ihr müsst die Kiste mit Ratten hier zu ihm bringen, bevor sie schlecht werden. Zackig!\n\nIhr seid doch wohl schon mal mit 'ner Bahn gefahren, oder? Ganz einfach. Steigt einfach ein, wenn sie kommt, und genießt die Fahrt. Und haltet Eure Arme und Beine während der Fahrt drinnen, wenn Ihr keine Holzgräten haben wollt.", sourceObjective = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Sturmwind.", progress = "<Nipsy steckt seinen Zeigefinger in eines der Luftlöcher des Kartons.>\n\nQuietschlebendig und zappelig... und genau zur richtigen Zeit!", completion = "Armer Monty. Seit dem Gnomeregan-Vorfall ist er ein anderer Mensch. Der Junge hat in seinem ganzen Leben noch kein Meer gesehen, ganz zu schweigen von irgendwelchen Piraten.\n\n<Nipsy seufzt.>\n\nZumindest sorgt er dafür, dass es immer Nachschub an quirligen Viechern gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6681] = { id = 6681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Anwesen, Rabenholdt", description = "{name},\n\nRabenholdt interessiert sich für Euch, junger Dieb. Wir haben Euch beobachtet. Euer Stil ist ein bisschen unbeholfen, aber daran können wir arbeiten.\n\nWenn Ihr bereit seid, eine Karriere als Schüler von Meister Rabenholdt in Angriff zu nehmen und Mitglied der Auftragsmörderliga zu werden, müsst Ihr nur das Siegel von Rabenholdt (diesem Brief beigefügt) zum Rabenholdtanwesen bringen.\n\nEure erste Aufgabe ist es, das Anwesen zu finden, das versteckt in den Hügeln des Hügellands liegt, um Eure Schlauheit zu demonstrieren.\n\nHochachtungsvoll,\n\nFahrad", sourceObjective = "Bringt das Siegel von Rabenholdt zu Fahrad im Rabenholdtanwesen, das versteckt in den Hügeln des Hügellands liegt.\n\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", progress = "Habt Ihr Milton getroffen?\n\n<Fahrad lacht.>", completion = "Äußerst exzellent, junger Dieb.\n\nIhr seht etwas mitgenommen aus, aber das wird schon wieder.\n\nEine lange Reise erwartet Euch - lang und profitabel. Seid Ihr bereit, Euer Schicksal unter den Meistern von Ravenholdt zu schmieden?\n\nSprecht mit den Wachen da draußen. Sie werden Euch einweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6701] = { id = 6701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syndikatsembleme", progress = "Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!\n\nWir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.\n\nRaubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.\n\nBeginnt in Durnholde südlich von hier.", completion = "He, gute Arbeit! Macht so weiter, dann hören die anderen Schurken vielleicht auf, Euch zu bespucken." }
quests[6721] = { id = 6721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[6722] = { id = 6722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[6741] = { id = 6741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Beute!", progress = "Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!", completion = "Und wieder muss ich euch danken, {name}.  Ihr macht der Horde alle Ehre..." }
quests[6761] = { id = 6761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Grenze", description = "Ich habe meinen Stellvertreter Mathrengyl Bärenfährte beauftragt, sich um die Bitte um Unterstützung der Mondlichtung zu kümmern. Sprecht mit ihm über diese Angelegenheit - NICHT mit mir.\n\nLasst mich Euch einen... gut gemeinten... Rat geben. ICH habe uns aus der Dunkelheit geführt - NICHT der Zirkel des Cenarius auf der Mondlichtung -, als für unser Volk alles verloren war. Teldrassil gibt uns allen neues Leben! Sie wollen Euch anderes glauben machen, und ihre Propaganda zu glauben, wäre reine Blauäugigkeit.\n\nIch werde es Euch überlassen, ob Ihr ein Narr sein wollt oder nicht.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus.", completion = "Vielen Dank, dass Ihr gekommen seid, {class}. Ich entschuldige mich für das Missverständnis... es gibt viel Misstrauen zwischen dem Erzdruiden hier und dem Bewahrer Remulos in Moonglade. Jeder verdächtigt den anderen der Schikane und die Tatsache, dass die merkwürdige Verderbnis von Teldrassil auch weiterhin nicht nachlässt, ist hier immer noch ein Thema. Das trägt wenig dazu bei, das Misstrauen zu lindern.\n\nTrotzdem bleibt unsere Pflicht gegenüber dem Zirkel des Cenarius bestehen... auch wenn diejenigen, die ihn leiten, untereinander uneins sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6762] = { id = 6762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabine Saturna", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos bei der Mondlichtung Unterstützung bei der Erforschung des riesigen Ödlands weit im Westen von Tanaris... und noch weiter im Westen von Un'Goro. Ihr solltet ihn in Nachthafen finden, dem Hauptort der Mondlichtung.\n\nEure Arbeit wird zwar zweifellos sehr vorteilhaft für uns sein, dennoch rate ich Euch, Vorsicht walten zu lassen. Es gibt Spannungen zwischen Darnassus und der Mondlichtung... Spannungen, die im Laufe der Zeit wachsen könnten.", sourceObjective = "Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung. Die Mondlichtung liegt zwischen dem Teufelswald und Winterquell, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Ich weiß außerdem, dass der Erzdruide von Darnassus sein Missfallen darüber ausgedrückt hat, dass Ihr uns unterstützt. Seid versichert, dass es zum Guten ist und dass Ihr gegen alle schlechten Auswirkungen gefeit seid, deren Ziel Ihr sein mögt.\n\nIhr seid hier unter Freunden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6781] = { id = 6781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Rüstungsfetzen", progress = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!", completion = "Das sind ein paar recht gute Stücke, {name}. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!" }
quests[6801] = { id = 6801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokholar der Eislord", progress = "Ich komme aus Thunder Bluff, {race}. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord diesen Hunden von den Stormpikeden ganzen Zorn des Frostwolfklans vor Augen führen!" }
quests[6804] = { id = 6804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftetes Wasser", description = "Eine Truppe von Elementarspähern wurde in die Östlichen Pestländer von Lordaeron entsandt und die Krankheit dieses Orts verdrehte und infizierte sie. Die Wasserlords können diese Beleidigung unserer Reinheit nicht dulden!\n\nNehmt diese Phiole. Darin befindet sich ein Quäntchen eines Aspekts von Neptulon. Wenn das auf die verseuchten Elementare angewendet wird, bekämpft es das Gift in ihren Körpern und heilt sie! Ihr innerer Konflikt wird sie allerdings in den lodernden Wahnsinn treiben.\n\nBesiegt die disharmonischen Wogen und bringt mir ihre Armschienen der Bindung.", sourceObjective = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der Östlichen Pestländer an. Bringt 12 disharmonische Armschienen sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.", progress = "Habt Ihr die Armschienen?", completion = "Ihr habt Eure Sache gut gemacht, {class}. Die verderbten Elementare, die Ihr geheilt habt, waren ein Frevel für alle Gewässer. Unsere Kraft liegt in unserer Reinheit und wenn wir unseren Krieg mit den anderen gewinnen wollen, müssen wir stark bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[6805] = { id = 6805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürmer und Rumpler", description = "Wir, die Elementare des Wassers, führen Krieg mit den Wesen der niederen Elemente. Wenn Ihr in diesem Konflikt wirklich unser Verbündeter seid, dann beweist mir Eure Überzeugung!\n\nWeit im Süden, im Wüstenland Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen, und obwohl ich nicht weiß, warum sie das tun, will ich ihre Bemühungen zunichtemachen.\n\nBegebt Euch zum Kristalltal in Silithus und besiegt unsere Feinde. Kehrt danach zu mir zurück.", sourceObjective = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.", progress = "Feigheit ist keine Sache, die wir begrüßen, {class}. Begebt Euch nach Silithus und beweist Euren Mut.", completion = "Euer Mut ist bewiesen, ebenso wie Euer Wert für uns. Vielleicht habe ich in der Zukunft Aufgaben für Euch, die sich eher eines geschätzten Verbündeten der Wasserlords ziemen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6821] = { id = 6821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge des Glutsehers", description = "Ihr habt mir gezeigt, dass Ihr unsere Feinde besiegen und Missionen ausführen könnt, um die Sache der Wasserlords weiter voranzutreiben. Aber bisher seid Ihr nur niederen Feinden gegenübergetreten... wenn Ihr gegen einen mächtigen Feind geschickt werdet, könnt Ihr dann siegen?\n\nDas ist Eure neue Aufgabe.\n\nHoch droben auf der Schwarzfelsspitze haben die Orcs einen Diener des Feuers gefangen genommen, die Feuerwache Glutseher. Sucht den Ort seiner Gefangenschaft, erschlagt seine Häscher und erschlagt dann den Glutseher. Bringt mir sein Auge. Das wird mir Euren Wert zeigen.", sourceObjective = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.", progress = "Habt Ihr das Auge, {class}? Seid Ihr stark genug, die Blackrockspitze zu betreten?", completion = "Ah, Ihr habt also die Kraft. Und Ihr habt auch die benötigte Schlauheit, denn die Blackrockspitze erfordert mehr als rohe Gewalt.\n\nIn der Tat, {name}, Ihr könntet Euch für uns noch als geschätzter Verbündeter erweisen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6822] = { id = 6822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmolzene Kern", description = "{name}, vielleicht ist es jetzt an der Zeit, Euch einem echten Test zu unterziehen. Seid Ihr bereit?\n\nAm Fuß der Schwarzfelstiefen befindet sich ein Durchgang zum Geschmolzenen Kern. Er ist eine Festung unseres Feindes, in der Hand des mächtigsten Dieners des Feuers in dieser Welt.\n\nBegebt Euch zum Geschmolzenen Kern, {name}. Zeigt mir, dass Ihr über die Kraft und den Willen verfügt, das zu besiegen, was Ihr dort finden werdet.\n\nUnd wenn Ihr Verbündete in Eurem Volk habt, dann versammelt sie. Nichts Geringeres als eine Armee kann hoffen, den Geschmolzenen Kern zu betreten und zu überleben.", sourceObjective = "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück.", completion = "Ihr habt getan, was die meisten Eurer Art für unmöglich halten würden. Ihr seid den Wesen des geschmolzenen Kerns gegenübergetreten und habt triumphiert!\n\nFür eine so kleine Kreatur habt Ihr großes Potenzial gezeigt.\n\nEines Tages erreichen wir möglicherweise ein echtes Bündnis zwischen Eurer Art und den Wasserlords.", sourceObjectiveStatus = "unverified-source-field" }
quests[6823] = { id = 6823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agent von Hydraxis", description = "Wenn Ihr wirklich ein Bündnis mit uns wünscht, dann schlage ich vor, dass Ihr Krieg gegen unsere Feinde führt, die Diener von Luft und Erde und Feuer. Jede Niederlage, die Ihr ihnen beibringt, wird ihren Stand hier schwächen und Eure Verbindung zu unserer Sache weiter untermauern.\n\nVor Euch liegen lange und harte Schlachten, doch wenn Ihr diese übersteht, so winken Euch Ruhm und Ehre.", sourceObjective = "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara.", completion = "Die Kunde Eurer Heldentaten gegen unsere Feinde hallt in der Kammer der Wasserlords wider, {name}. Einige waren der Meinung, dass Eure Gestalt zu klein und zerbrechlich sei, um in unserem Krieg zu kämpfen, aber Ihr habt viel gewonnen. Ihr habt Euch unter uns Respekt verdient, ein unglaubliches Kunststück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6824] = { id = 6824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände des Feindes", description = "{name}, Euer Dienst ist für uns von großem Wert, und daher zögern wir, Euch auf diese letzte Mission zu schicken, denn wir wollen einen solch nützlichen Agenten nicht verlieren.\n\nAber der Erfolg würde unsere Kriegsbemühungen ungeheuer voranbringen und... das wird als ausreichend erachtet, Euer Leben zu riskieren.\n\nWir wollen, dass diese Hauptmänner im Geschmolzenen Kern vernichtet werden: Lucifron, Sulfuron, Gehennas und Shazzrah. Tötet sie und bringt mir ihre Hände!\n\nDiese Aufgabe wird Euer ganzes Können erfordern, {name}, aber wenn Ihr erfolgreich seid, dann wird den Feuerlords ein schrecklicher Schlag versetzt.", sourceObjective = "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara.", progress = "Habt Ihr Lucifron und die anderen besiegt, {name}? Habt Ihr die Hände des Feindes?", completion = "Ihr habt die Hände! Die besiegten Feuer-Captains! Ich hätte es nicht für möglich gehalten, wenn ich Euch nicht kennen würde und wüsste, wozu Ihr fähig seid.\n\n{name}, Eure Heldentaten sind ohne Zahl, aber die Kunde von dieser letzten Heldentat wird unter den Wasserlords Wellen schlagen. Euer Name könnte eines Tages eine Legende unter uns sein.\n\nSprecht wieder mit mir, {name}. Ich habe möglicherweise noch eine weitere Aufgabe ...", sourceObjectiveStatus = "unverified-source-field" }
quests[6825] = { id = 6825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Guses Luftflotte", progress = "Wir müssen die neue Flotte von Kriegsreitern vorbereiten, {race}! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.\n\nIch benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!", completion = "Die Flotte ernährt sich von ihrem Fleisch. Sie verzehrt den Feind.\n\nDer Flug steht unmittelbar bevor!" }
quests[6826] = { id = 6826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Jeztors Luftflotte", progress = "Ihr habt hart gearbeitet, {name}, aber wir haben gerade erst begonnen!\n\nMeine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!\n\nMeine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.\n\nSputet Euch!", completion = "Mehr! Mehr! Bringt mehr, denn sie müssen bald bereit sein!" }
quests[6827] = { id = 6827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Mulvericks Luftflotte", progress = "Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!\n\nWir müssen alles sorgfältig planen.\n\nZuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch.", completion = "Nicht genug! Solch eine Arbeit würde ich von einem Initianden erwarten, aber von Euch, {name}? Kommt schon! LASST KNACKEN! Es wird mehr Fleisch benötigt!" }
quests[6844] = { id = 6844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umber, Archivar", description = "Hier gibt es immer noch viel zu tun, aber ich denke, es ist wichtig, dies zur Analyse zum Zirkel zurückzubringen. Vertraut mir - es wird immer noch Arbeit geben, wenn das alles erledigt ist. Wenn sich in diesem klebrigen Chitin ein Tagebuch befindet, hätte der Zirkel endlich ein Fenster zur Vergangenheit geöffnet!\n\nBringt dies zum Archivar des Zirkels in Nachthafen. Sein Name ist Umber und er ist brillant. Er ist etwas eigenartig, sicher, aber trotzdem brillant! Umber hat schon Folianten gerettet, die in wesentlich schlechterem Zustand waren als dieser hier. Wenn dieser gerettet werden kann, dann schafft er es.", sourceObjective = "Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nachthafen auf der Mondlichtung.", progress = "Oh, hallo! Hrmm...\n\nLasst mich ehrlich zu Euch sein... Ihr riecht ein wenig streng. Abgestanden, könnte man sagen. Aber ich möchte Eure Person nicht angreifen. Ich sage nur... in Zukunft solltet Ihr Euch ein wenig frisch machen, wenn Ihr vom Schlachtfeld kommt. Damit könnte der erste Eindruck wesentlich positiver ausfallen!\n\nAber egal... was kann ich für Euch tun?", completion = "Heiliger Bimbam! Was habt Ihr denn da? Ich würde sagen, es hat die Form eines Buches... Ich werde versuchen, die Schale darum aufzubrechen.\n\nLayo hat Euch aus Silithus zu mir geschickt? Ich habe nur ein paar geflüsterte Gerüchte gehört - die ja wohl nicht unbedingt geflüstert sind, wenn man's genau nimmt - über die Schrecken, die dort draußen vor sich gehen. Verbindet das mit meiner Abneigung gegen alles Käferähnliche und Ihr habt ein Rezept, damit ich hier bei diesen Büchern bleibe!", sourceObjectiveStatus = "unverified-source-field" }
quests[6845] = { id = 6845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllung von Geheimnissen der Vergangenheit", description = "Tja, Ihr solltet möglichst bald wieder zu mir kommen... falls Ihr wissen wollt, was sich hier drinnen befand. Sobald ich herausfinde, was es ist, und falls es in der Tat ein Buch ist, werde ich diese Informationen gern mit Euch teilen.\n\nIn der Zwischenzeit solltet Ihr Euch an die Höhlenmutter dieses kleinen Bärenlagers wenden, Rabine. Es ist bestimmt für alle interessant zu wissen, was für verrückte Dinge Ihr so erlebt habt. Lasst die Höhlenmutter niemals warten, {name}... zumindest nicht, wenn Ihr nicht in Honig getaucht werden wollt.\n\nDas ist schon passiert, glaubt mir.", sourceObjective = "Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung.", completion = "Ah, {name}... ich hatte gehofft, dass Ihr vorbeikommen würdet. Es ist schön, Euch gesund und munter zu sehen.\n\nIch hatte Nachricht erhalten, dass Ihr vom Schlachtfeld herkommen würdet, und ich wollte persönlich die Dankbarkeit des Zirkels des Cenarius für die Unterstützung zum Ausdruck bringen, die Ihr uns bisher angedeihen ließet. Zweifellos gibt es noch weitere Geheimnisse über die Silithus zu enthüllen. Eure Lieferung an Umber sollte sich als sehr interessant erweisen, wenn sie erst enthüllt ist. Nehmt dies bitte als Zeichen unserer kontinuierlichen Wertschätzung für Eure Hilfe.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6846] = { id = 6846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff soll beginnen!" }
quests[6847] = { id = 6847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Rysons Allsehendes Auge", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, {class}. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>", sourceObjective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[6848] = { id = 6848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Rysons Allsehendes Auge", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, {class}. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>", sourceObjective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[6861] = { id = 6861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinnzischelix's tragbare Schreddereinheit", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, {race}, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Sturmlanzen aufgefallen.", sourceObjective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", sourceObjectiveStatus = "unverified-source-field" }
quests[6862] = { id = 6862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinnzischelix's tragbare Schreddereinheit", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, {race}, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Frostwölfe aufgefallen.", sourceObjective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", sourceObjectiveStatus = "unverified-source-field" }
quests[6881] = { id = 6881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivus der Waldfürst", progress = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, {name}!", completion = "Gut gemacht, {name}. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen." }
quests[6901] = { id = 6901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startet den Angriff!" }
quests[6921] = { id = 6921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inmitten der Ruinen", description = "Die Anhänger des Schattenhammers sind in die Mondschreinruinen der Tiefschwarzen Grotte eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n{name}, geht in die Tiefschwarze Grotte und findet den Tiefenstein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", sourceObjective = "Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", progress = "Konntet Ihr den Fathom-Kern finden? Ohne ihn haben wir keine Ahnung, was genau die Twilight-Hammer da unten vorhaben.", completion = "Genau das brauche ich! Ein Fathom-Kern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Twilight-Hammer da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann -, meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6922] = { id = 6922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgt hat. In der Kugel schwappt faulig aussehendes Wasser herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring.", sourceObjective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea in der Tiefschwarzen Grotte.", progress = "Ach, hallo, {name}. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... das ist ein wichtiger Fund, {name}.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[6941] = { id = 6941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Vipores Luftflotte", progress = "Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen.", completion = "Der Klan wird bald bereit sein. Setzt Eure Bemühungen fort!" }
quests[6942] = { id = 6942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Slidores Luftflotte", progress = "Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.\n\nDie Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.\n\nWenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!", completion = "Immer her damit, Soldat! Die Aerie-Greifen werden im Handumdrehen bereit sein zuzuschlagen!" }
quests[6943] = { id = 6943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Lüfte - Ichmans Luftflotte", progress = "Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.\n\nKehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!", completion = "Seht Ihr es? Schaut sie Euch an! Sie rappeln sich wieder auf... Bald wird Ichmans Klan erneut im Herzen des Tales zuschlagen! Stormpike wird den Himmel beherrschen!" }
quests[6961] = { id = 6961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altvater Winter ist hier!", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... ''Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\n Wenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[6962] = { id = 6962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckereien für Altvater Winter", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freude machen und das für mich besorgen?", sourceObjective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar.", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam schon selbst ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, {name}. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6963] = { id = 6963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Winterhauchleckereien", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, das an das Vorgebirge des Hügellands angrenzt und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", sourceObjective = "Sucht den Ermittler von Kokelwälder, der in den verschneiten Regionen des Vorgebirges des Hügellands vermisst wird.", completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Orgrimmar. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", sourceObjectiveStatus = "unverified-source-field" }
quests[6964] = { id = 6964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anlass für die Feiertage", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann fragt Sagorne Gratläufer. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", sourceObjective = "Sprecht mit Sagorne Gratläufer im Tal der Weisheit von Orgrimmar über das Winterhauchfest.", completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Tauren eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende dieser Feiertage der Erneuerung zur verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Furmund diese Veränderung bitter aufstößt. Er und andere Tauren wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[6981] = { id = 6981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der leuchtende Splitter", description = "Der Splitter ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Ihr fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt Ihr auch, dass etwas sehr Beunruhigendes von ihm ausgeht.\n\nVielleicht solltet Ihr in Ratschet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", sourceObjective = "Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\n\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.", progress = "Hallo, {race}. Was kann ich für Euch tun?", completion = "Oh... So etwas habe ich noch nie gesehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6982] = { id = 6982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine ist ein Vorratslager für die Horde. Ich vertrage das Essen nicht, das sie ihren Truppen reichen und der Zustand ihrer Waffen und Rüstungen ist grauenhaft! Aber... in Zeiten wie diesen, in denen Vorräte so wichtig sind, können wir wirklich alles verwenden, was sie haben. \n\nBetretet die Eisbeißermine und bringt mir ihre Vorräte. Dies sollte der Allianz helfen sich weiterhin gut im Kampf zu bewähren und die Soldaten der Horde schwächen.\n\nViel Erfolg, {name}. Die Mine ist im entfernten Süden, tief im Territorium der Horde.", sourceObjective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Allianz in Dun Baldar.", progress = "Habt Ihr die Coldtooth-Mine im Gebiet der Horde betreten, {name}? Habt Ihr die Vorräte?", completion = "Ihr habt sie! Gut gemacht, {name}! Ich werde dann mal durch die Vorräte durchgehen und sehen was wir für unsere Truppen gebrauchen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[6983] = { id = 6983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So was Gemeines...", description = "Eine Kreatur namens \"Der monströse Griesgram\" hat unsere Lieferung mit Leckereien gestohlen, {name}. Seid aber vorsichtig! Er ist bösartig und befiehlt über ein paar dieser kleinen grünen Gnome!\n\nIhr werdet Hilfe brauchen, wenn Ihr ihm gegenübertretet. Ich habe gehört, dass er unsere Leckereien und Metzen, unser geliebtes Rentier, in die Eisfellhöhle im Vorgebirge des Hügellandes gebracht hat. Findet die Leckereien, {name}, und bringt sie zurück nach Orgrimmar, bevor das Fest ruiniert ist und all die Kinder enttäuscht werden!", sourceObjective = "Sucht die gestohlenen Leckereien und befreit Metzen das Rentier, nachdem Ihr den monströsen Griesgram besiegt habt. Er verbirgt sich nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", progress = "{name} - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nKokelwälder verehrt Euch dafür und natürlich tun das auch all die Kinder!", sourceObjectiveStatus = "unverified-source-field" }
quests[6984] = { id = 6984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dankeschön von Kokelwälder!", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, {name}. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost... dank Euch natürlich!", sourceObjective = "Sprecht mit Altvater Winter in Orgrimmar.", completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[6985] = { id = 6985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisenschachtmine", description = "Die Zwerge der Sturmlanzen benutzen die Eisenschachtmine als ein Vorratslager. Ich möchte, dass Ihr diese Mine überfallt und mir ihre Vorräte bringt. Dies sollte die Bemühungen der Sturmlanzen im Alteractal behindern und uns mit der nötigen Ausrüstung versorgen!\n\nSeid vorsichtig, {name}. Die Eisenschachtmine liegt tief im Territorium der Allianz, und die Kontrolle über die Mine ändert sich so oft wie neuer Schnee in Alterac fällt.", sourceObjective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf.", progress = "Wart Ihr in der Irondeep-Mine, {name}? Habt Ihr die Vorräte geplündert?", completion = "Ihr habt Sie! Gute Arbeit, {name}! Hoffentlich habt Ihr unterwegs noch ein paar Zwerge getroffen und ihr Blut im Namen der Frostwolf vergossen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7001] = { id = 7001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwaiste Ställe", description = "Der Krieg hier im Tal hat viele Opfer gefordert. Unsere Streitkräfte müssen dringend wieder aufgebaut werden!\n\nWenn wir es schaffen unsere Ställe wieder zu füllen, können unsere glorreichen Wolfsreiter wieder in die Schlacht reiten.\n\nNehmt diesen Maulkorb und begebt Euch in die nahegelegenen Wälder. Sucht in der Umgebung nach herumstreifenden Frostwölfen und fangt sie mit dem Maulkorb ein. Wenn Ihr einen Wolf gezähmt habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen.\n\nSobald wir wieder über ausreichend Wölfe verfügen, werden die Wolfsreiter ihre Frontpatrouillen fortsetzen.", sourceObjective = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", progress = "Ohne Eure Hilfe, hätten die Frostwolfreiter keine Reittiere um in die Schlacht zu ziehen. Ihr erweist uns einen großen Dienst!", completion = "Ich kann nur hoffen das andere die mit dem Sammeln von Widderbälgern beauftragt wurden, ebenso motiviert sind wie Ihr, {name}.\n\nBei diesem Arbeitstempo, werden die Ställe in wenigen Stunden wieder voll sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[7002] = { id = 7002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widderledernes Zaumzeug", progress = "Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?\n\nIhr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.\n\nTötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!" }
quests[7003] = { id = 7003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschrumpfte Riesen", description = "Ich muss etwas gegen die Riesen unternehmen, wenn ich hier draußen bleibe! Sie sind sicherlich nicht gut fürs Geschäft, oder nicht?\n\nIch habe mich an einer Variante von Gnomischen Schrumpfstrahlen versucht, benutze jetzt aber überlegene GOBLIN Technologien für die Herstellung! Im Zuge von Bemühungen, Unannehmlichkeiten wie meinen Tod beispielsweise zu vermeiden, möchte ich Euch bitten es einmal an diesen Riesen in Feralas zu testen. Ihr solltet nach dem Prozess Schrumpfüberreste auf ihnen finden, bringt mir bitte etwas davon!", sourceObjective = "Benutzt Zorbins Ultraschrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin von Schiller 15 Schrumpfüberreste von diesen Riesen. Ihr findet ihn bei den Docks, an der Vergessenen Küste in Feralas.", progress = "Schrumpf-Überreste, versichere Ich Euch, sind eine wertvolle Handelsware, was das Ingenieurswesen angeht! Nunja, es ist insofern schon wertvoll, als dass es mir hilft den Schrumpfer zu kontrollieren, sodass er nicht beim Benutzen explodiert.\n\nOh, natürlich meine ich andere Schrumpfer als den, den ich Euch gab. Natürlich ist es ein anderer!", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh,... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultra-Schrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, {name}. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[7021] = { id = 7021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altvater Winter ist hier!", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7022] = { id = 7022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altvater Winter ist hier!", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7023] = { id = 7023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altvater Winter ist hier!", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Eisenschmiede befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien vonKokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7024] = { id = 7024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altvater Winter ist hier!", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7025] = { id = 7025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckereien für Altvater Winter", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freunde machen und das für mich besorgen?", sourceObjective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Eisenschmiede.", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam selbst schon ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, {name}. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[7026] = { id = 7026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widderzaumzeug", progress = "Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!\n\nWir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.\n\nIhr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!" }
quests[7027] = { id = 7027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwaiste Ställe", description = "Seht Euch nur unsere Ställe an, {name}! Völlig leer! Die Sturmlanzengarde hat keine Widder mehr, die sie reiten könnte, die Kavallerie ist praktisch nicht mehr existent.\n\nIhr müsst uns helfen, Soldat. Nehmt dieses Zähmungshalsband und begebt Euch in die Wildnis dieses Tals. Sucht in der Umgebung nach herumstreifenden Alteracwiddern und fangt sie mit dem Zähmungshalsband ein. Wenn Ihr einen Widder eingefangen habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen. Sobald wir wieder über ausreichend Widder verfügen, werde ich den Kommandanten der Widderreiter informieren.\n\nMit Eurer Hilfe wird die Kavallerie neu entstehen!", sourceObjective = "Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Zähmungshalsband der Sturmlanzen um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", progress = "Ohne Eure Hilfe hätten die Stormpike Widderreiter jetzt keine Reittiere, um in die Schlacht zu ziehen. Ihr habt uns einen großen Dienst erwiesen!", completion = "Nicht mehr lange und die Ställe sind wieder voll! Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[7028] = { id = 7028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Böses", description = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon... Das ist ein uralter Ort mit einer langen Geschichte. Und ich will einiges davon in die Hände bekommen, {class}. Relikte der Alten Götter liegen hinter den riesigen Türen verborgen.\n\nWenn Ihr bereit seid, dem dunklen Bösen zu trotzen, das sich in Maraudon findet, wird es Euer Schade bestimmt nicht sein. Sammelt die theradrischen Kristallschnitzereien ein, die Ihr aufstöbern könnt, und bringt sie mir.\n\nSobald ich die Schnitzereien habe, kann ich sie... studieren. Diese Mächte haben schon zu lange geruht...", sourceObjective = "Sammelt 15 theradrische Kristallschnitzereien für Trista in Desolace.", progress = "Stellt keine Fragen!\n\nIhr wisst, was ich will.", completion = "Ha ha ha! Ich wusste, Ihr würdet zurückkehren.\n\n<Willow murmelt vor sich hin.>\n\n... So leicht zu überzeugen.\n\n... Würde alles tun, solange der Preis stimmt. Hi, hi, hi…", sourceObjectiveStatus = "unverified-source-field" }
quests[7029] = { id = 7029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenzunges Verderbnis", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, {name}. Füllt sie am orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", sourceObjective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück.", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, {name}...", completion = "Danke, dass Ihr das zurückgebracht habt, {name}. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[7041] = { id = 7041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenzunges Verderbnis", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, {name}. Füllt sie am verderbten orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", sourceObjective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, {name}...", completion = "Danke, dass Ihr das zurückgebracht habt, {name}. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[7042] = { id = 7042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Winterhauchleckereien", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen - von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, das an das Vorgebirge des Hügellands angrenzt und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", sourceObjective = "Sucht den Ermittler von Kokelwälder, der in den verschneiten Regionen des Vorgebirges des Hügellands vermisst wird.", completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Ironforge. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", sourceObjectiveStatus = "unverified-source-field" }
quests[7043] = { id = 7043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So was Gemeines...", description = "Eine Kreatur namens \"Der monströse Griesgram\" hat unsere Lieferung mit Leckereien gestohlen, {name}. Seid aber vorsichtig! Er ist bösartig und befiehlt über ein paar dieser kleinen grünen Gnome!\n\nIhr werdet Hilfe brauchen, wenn Ihr ihm gegenübertretet. Ich habe gehört, dass er unsere Leckereien und Metzen, unser geliebtes Rentier, in die Eisfellhöhle im Vorgebirge des Hügellandes gebracht hat. Findet die Leckereien, {name}, und bringt sie zurück, bevor das Fest ruiniert ist und all die Kinder von Sturmwind enttäuscht werden!", sourceObjective = "Sucht die gestohlenen Leckereien und befreit Metzen das Rentier, nachdem Ihr den monströsen Griesgram besiegt habt. Er verbirgt sich nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", progress = "{name} - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nKokelwälder verehrt Euch dafür und natürlich auch all die Kinder!", sourceObjectiveStatus = "unverified-source-field" }
quests[7044] = { id = 7044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden von Maraudon", description = "Ein dunkler Satyr namens Lord Schlangenzunge hat sein Böses in diesen verschlungenen Höhlen verbreitet und die Gedanken aller im Inneren vergiftet. Er residiert noch jenseits der lila Kristalle.\n\nSchlangenzunge hat des Weiteren ein lebendes Symbol seiner Verderbnis namens Noxxion geschaffen, das sich hinter den orangefarbenen Kristallen befindet. Zusammen haben sie die beiden Teile des Szepters meines Bruders gestohlen. Celebras, mein Bruder... wandert blind im Inneren umher, verflucht durch die Verderbnis.\n\nIhr müsst ihm helfen! Findet die Stücke und sprecht mit meinem Bruder...irgendwie.", sourceObjective = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\n\nFindet einen Weg, um mit Celebras zu sprechen.", progress = "Ich bin aus einem Alptraum erwacht, der niemals enden wollte...", completion = "Da Ihr nun die beiden Teile meines Szepters zurückgeholt habt, hoffe ich, dass Maraudon eines Tages von der Vyle-Verderbnis befreit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[7045] = { id = 7045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dankeschön von Kokelwälder!", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, {name}. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost... dank Euch natürlich!", sourceObjective = "Sprecht mit Altvater Winter in Eisenschmiede.", completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[7046] = { id = 7046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Szepter von Celebras", description = "Mein Szepter war einst eine Quelle der Hoffnung für mich. Es gewährte mir einst die Macht über diese Höhlen. Ich hatte gehofft, dem Geist meines Onkels Frieden bringen zu können...\n\nDamit die beiden Teile wieder eins werden können, benötige ich Eure Hilfe bei der Durchführung des Rituals. Folgt mir bitte und hört auf meine Anweisungen, während ich die Energie kanalisiere, die erforderlich ist, um den Griff wieder mit dem Diamanten zu vereinigen.\n\nZusammen werden wir das Szepter von Celebras wieder erschaffen!", sourceObjective = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\n\nSprecht mit ihm, nachdem das Ritual vollendet ist.", completion = "Bitte nehmt dies und wisset, dass die Macht, die Euch zugeteilt wurde, nur genutzt werden darf, um Gutes zu tun. Setzt Eure Reise durch diese Höhlen fort, und vielleicht werdet Ihr die Überreste meines Onkels finden. Große Gefahren liegen vor Euch, {name}.\n\nSprecht erneut mit mir, falls es nötig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[7061] = { id = 7061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Winterhauchfest", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als jemand, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, bringt das Buch zu Baine Bluthuf in Donnerfels. Ich weiß mit Bestimmtheit, dass es ihm nicht gleichgültig ist, wenn auch andere sich für die Lehre unseres Volkes interessieren.", sourceObjective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Baine Bluthuf in Donnerfels.", progress = "Ich heiße Euch in Mulgore und unserem bescheidenen Gemeinwesen Thunder Bluff willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Ja, ich weiß, dass die Goblins aus recht eigennützigen Motiven dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unser Volk zumindest auf eine Art damit beschäftigt, hilft, diese Lehre am Leben zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, {class}. Ich verbeuge mich vor Eurer Weisheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[7062] = { id = 7062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anlass für die Feiertage", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann befragt den Historiker Karnik in der Forscherliga. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", sourceObjective = "Sprecht mit dem Historiker Karnik in der Forscherliga von Eisenschmiede über das Winterhauchfest.", completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Zwerge eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende von Altvater Winter zu einer verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Goli diese Veränderung bitter aufstößt. Er und andere Zwerge wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[7063] = { id = 7063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Winterhauchfest", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als Gelehrter, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, dann bringt das Buch zu Muradin Bronzebart. Ich weiß mit Bestimmtheit, dass es ihn sehr interessieren wird, wenn auch andere Interesse für die alten Legenden an den Tag legen.", sourceObjective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, dann bringt es zu Muradin Bronzebart nach Eisenschmiede.", progress = "Ich heiße Euch im Königreich Ironforge willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Mir ist durchaus bewusst, dass die Goblins, wenn auch aus recht eigennützigen Motiven, dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unsere Bevölkerung zumindest auf eine gewisse Art mit dieser Lehre beschäftigt, hilft, sie lebendig zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, {class}. Ich verneige mich vor Eurem gelehrten Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7064] = { id = 7064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis von Erde und Samenkorn", description = "Tief in Maraudon lebt eine böse Kreatur des Chaos - Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den Alten Göttern verwandt ist. Vor langer Zeit gingen sie und Zaetar, der erstgeborene Sohn von Cenarius, eine Beziehung ein. Aus ihrer gemeinsamen Zeit entsprangen Wesen, die unter den Menschen von Kalimdor als Zentauren bekannt wurden. Diese undankbaren Kreaturen töteten Zaetar und bewachen nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", sourceObjective = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Schattenflucht in Desolace zurück.", completion = "Das sind wirklich ganz wunderbare Nachrichten, {name}! Danke!\n\nIch werde mit Marandis sprechen und um sein Wissen zum Thema Zaetars Überreste bitten, aber zumindest habt Ihr die schwierigste der Aufgaben bereits bewältigt.\n\nMir wurde gesagt, dass ich diejenigen belohnen darf, die uns geholfen haben, wenn wir bei unserer Mission erfolgreich sein sollten. Als Geschenk unseres Volkes habe ich diese Gegenstände erhalten - wählt einen davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[7065] = { id = 7065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis von Erde und Samenkorn", description = "In den Tiefen von Maraudon lebt eine Kreatur des Chaos und des Bösen, {name}. Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den Alten Göttern verwandt ist. Vor langer Zeit stattete Zaetar, der erstgeborene Sohn von Cenarius, ihr einen Besuch ab. Die Nachkommen ihrer...Beziehung sind jene Kreaturen, die unter dem Namen Zentauren bekannt sind. Diese undankbaren Kreaturen töteten Zaetar und Theradras bewacht nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", sourceObjective = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", completion = "Das sind wirklich ganz wunderbare Nachrichten, {name}! Danke!\n\nEs beunruhigt mich zwar, dass Ihr die Überreste von Zaetar nicht zurückbringen konntet, aber wer bin ich, dass ich den Willen des Erstgeborenen von Cenarius in Frage stelle? Vielleicht wird der Wille der Zentauren nun brechen und ihr Blutdurst versiegen - wir können es nur hoffen.\n\nFür den Fall, dass unsere Mission von Erfolg gekrönt sein sollte, habe ich diese Gegenstände erhalten, um jene zu belohnen, die uns halfen. Ihr dürft einen dieser Gegenstände als Zeichen der Dankbarkeit wählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7066] = { id = 7066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samenkorn des Lebens", description = "Diese missratenen Zentauren - meine Söhne und Töchter - brauchen ihren Vater.\n\nSeht Euch um - dieser Ort hallt wider von Hoffnung und all jenem, was mein Vater Cenarius predigt. All das entsprang aus mir! Und ich kann ihnen das nicht nehmen... nicht einmal ob ihrer Verbrechen gegen mich.\n\nEines jedoch möchte ich von Euch erbitten, damit mein Bruder Ruhe findet. Nehmt dies... es ist das erste Samenkorn, das aus dem Leben entstand, das meine Überreste nährten. Sagt ihm, dass mein Geist hier bleibt und dass ich weiterlebe. Er wird es sicherlich verstehen.", sourceObjective = "Sucht Remulos bei der Mondlichtung auf und gebt ihm das Samenkorn des Lebens.", progress = "Euch haftet der Geruch der Verderbnis an, {name}... wie so vielen Abenteurern in diesen Tagen. Aber etwas an Euch ist anders. Gibt es etwas, über das Ihr mit mir sprechen wollt? Ihr seid von einer Aura umgeben, die vertraut scheint, aber ich kann sie nicht einordnen.\n\nBitte, ich flehe Euch an, sagt mir, warum Ihr mich sehen wolltet.", completion = "Mein Bruder hat also endlich seinen Frieden gefunden? Ich bin stolz, dass ich diesen Tag erleben darf. In seiner ganzen Arroganz und seiner Wut dachte ich wahrlich, er wäre für uns verloren, aber dieses... dieses Symbol seines Opfers beweist eindeutig, dass er nicht verloren ist - er wurde nur neu geboren. Er nimmt seinen Platz in der Natur ein, wie es seine Pflicht war.\n\nIch danke Euch, {name}. Indem Ihr mir dies brachtet, habt Ihr mir ein wenig Hoffnung geschenkt, die ich schon für vergeblich hielt. Dieses Samenkorn wird für die Menschen in diesem vom Krieg zerrissenen Land eines Tages wichtig sein... Das kann ich spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[7067] = { id = 7067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anweisungen des Pariahs", description = "Obwohl ich als Ketzer verbannt wurde, bleibe ich meinem Glauben treu - das allein treibt mich voran. Aber damit mein Schicksal sich erfüllt, benötige ich die Hilfe eines Außenstehenden... jemanden, der keinem Zentaurenstamm angehört.\n\nFür diese Aufgabe muss jemand die heiligen Hallen von Maraudon betreten - das ist ein Tempel, den mein Volk schützt, und nur die Gläubigsten dürfen ihn betreten.\n\nWenn Ihr einwilligt, mir zu helfen, dann müsst Ihr nur nicken. Ich werde Euch ein Pergament mit meinen Anweisungen geben. Lest es durch und denkt über meine Worte nach.", sourceObjective = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.", progress = "Wie habt Ihr Euch entschieden, {name}? Könntet Ihr mir helfen? Werdet Ihr Euren Fuß auf heiligen Boden setzen, um mir zu helfen, einen großen Zentaurenstamm zu schmieden!?", completion = "Das ist es, {race}! Das ist es! Jetzt kann ich die große Aufgabe der Vereinigung der Stämme angehen. Seid bedankt.\n\nNehmt bitte dies für Eure Bemühungen. Ich hoffe, dass über unserem nächsten Treffen ein glücklicherer Stern stehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[7068] = { id = 7068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattensplitter", description = "Man findet starke Magie am heiligen Ort der Zentauren... dem heiligen Ort von Maraudon. Die Desolace-Stämme der Zentauren schützen diesen Ort mit ihrem Leben, aber sie können uns nicht davon abhalten, das zu nehmen, was wir brauchen.\n\nBegebt Euch zu diesem Maraudon-Ort und sucht nach den Felskreaturen, die aus Schattenstein bestehen. Bringt mir die lila Kristalle und Uthel'nay wird Euch Eure Mühe vergelten.\n\nDer Ort ist gefährlich, daher solltet Ihr einige Freunde mitnehmen.", sourceObjective = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.", progress = "Habt Ihr die Kristalle schon gefunden? Rituale der Macht, Zauber von großer Kraft - diese Schattensplitter könnten bei allen Arten arkaner Magie hilfreich sein.", completion = "Ah, diese sind perfekt für meine Magie. Hier, nehmt eines dieser Schmuckstücke und macht Euch auf den Weg... ich habe hier viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[7070] = { id = 7070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattensplitter", description = "Ich habe kürzlich begonnen, verschiedene Kristalle und ihre arkanen Eigenschaften zu testen. Lady Prachtmeer hat mir die Erlaubnis erteilt, Reisende, die nach Desolace ziehen, zu bitten, einen Ort zu suchen, der Maraudon genannt wird. In dem zerfallenen Tempel dort gibt es große Elementare, die aus lila Steinen bestehen. Ich habe sie Schattensplitter getauft.\n\nFalls Ihr beschließt, diese Richtung einzuschlagen, und dort einige dieser Kristalle findet, wäre ich sehr dankbar. Ich würde Euch sogar ein Schmuckstück daraus herstellen, wenn Ihr dies wünscht.", sourceObjective = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Düstermarschen.", progress = "Habt Ihr die Reise schon unternommen? Ich weiß, dass es recht gefährlich ist, aber wenn Ihr Erfolg habt, soll es Euer Schaden nicht sein.", completion = "Die sind perfekt, {name}. Es sind bereits andere Abenteurer von dort zurückgekehrt, und dadurch konnte ich dies herstellen... bitte, nehmt eines der Stücke für Eure harte Arbeit. Und ich danke Euch nochmals, dass Ihr mir weitere Proben für meine Studien besorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7081] = { id = 7081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Friedhöfe im Alteractal", description = "Die Friedhöfe im Alteractal sind äußerst wertvolle Gebiete. Beide Seiten, die Horde und die Allianz, kämpfen verbissen um diese geheiligten Stätten. {name}, seid Ihr bereit die Kämpfe zu unterstützen?\n\nIch möchte, dass Ihr einen gegnerischen Friedhof besetzt. Sucht einen Friedhof mit einem Banner der Horde in seiner Mitte und reißt es heraus! Wenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es schaffen, den Friedhof für einige Minuten zu halten, werden unsere Verstärkungstruppen eintreffen, um Euch bei der Verteidigung zu unterstützen.", sourceObjective = "Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", progress = "{name}, Ihr habt noch keinen Friedhof erobert. Kommt zu mir zurück, wenn Ihr Erfolg hattet.", completion = "Gute Arbeit! Friedhöfe sind lebenswichtig für unseren Einfluß im Alteractal. Mit jedem Friedhof den Ihr erobert, helft Ihr der Allianz dabei, ihre Herrschaft im Tal zu sichern. \n\nGeht nun, {name}.  Zieht wieder in die Schlacht, und falls Ihr einen von der Horde besetzten Friedhof seht... Ihr wißt ja was zu tun ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[7082] = { id = 7082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Friedhöfe von Alterac", description = "Die Frontlinien in diesem Tal sind in ständiger Bewegung. Die Gebietsgrenzen bewegen sich hin und her, während wir unseren Feinden in tödlichen Schlachten gegenüber treten. Doch um die Friedhöfe, {name}, wird am grimmigsten gekämpft.\n\nIch möchte, dass Ihr einen von der Allianz besetzten Friedhof angreift! Sucht einen Friedhof mit einem Banner der Allianz in seiner Mitte und reißt es aus dem Boden.\n\nWenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es außerdem schaffen, den Friedhof für einige Minuten zu halten, wird dieser uns gehören und unsere Truppen werden kommen, um Euch bei der Verteidigung dieser wichtigen Position zu unterstützen.", sourceObjective = "Erobert einen Friedhof und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück.", completion = "Gute Arbeit, {name}! Mit jedem weiteren Friedhof den wir kontrollieren, wandern die Geister unserer Feinde mehr und mehr verloren und ziellos herum.", sourceObjectiveStatus = "unverified-source-field" }
quests[7101] = { id = 7101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme und Bunker", description = "Die Türme und Bunker in diesem Tal sind wichtige Stellungen und daher müssen wir sie möglichst alle erobern und halten! Genug geredet... Erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Banner der Allianz. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Banner der Horde wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Allianz es zurückgewinnt, gehört es uns!", sourceObjective = "Erobert einen gegnerischen Turm und kehrt anschließend zu Korporal Teeka Murrblut im Alteracgebirge zurück.", completion = "Ich habe von Eurer erfolgreichen Mission gehört! So gefällt mir das...\n\nunsere Truppen nun ungehindert die feindlichen Stellungen stürmen. Bald werden diese Schwächlinge einsehen das, dass Alteractal kein Ort für sie ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[7102] = { id = 7102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme und Bunker", description = "Die Türme und Bunker in diesem Tal sind Schlüsselverteidigungspositionen und daher sollten wir so viele wie möglich davon unter Kontrolle halten! Geht und erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Banner der Horde. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Banner der Allianz wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Horde es zurückgewinnt, gehört es uns!", sourceObjective = "Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", completion = "Ich habe eine Feldnachricht erhalten, nach der Ihr dabei geholfen habt ein feindliches Banner zu sichern. Gute Arbeit, {name}! Nach der Vernichtung der feindlichen Schützen können wir weiter ins Feindesland vordringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7121] = { id = 7121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rüstmeister", description = "{name}, unser Rüstmeister hat mich angewiesen, die neuen Rekruten direkt zu ihm zu schicken. Er benötigt dringend Vorräte aus Kisten, die in den Minen von Alterac eingelagert sind und aller Wahrscheinlichkeit nach wird er Euch entsenden, um sie zu beschaffen.\n\nFolgt einfach der Straße. Ihr findet den Rüstmeister im Westen.", sourceObjective = "Sprecht mit dem Rüstmeister der Sturmlanzen.", completion = "Ah, endlich sind frische Truppen eingetroffen, {name}. Mit etwas Glück könnt Ihr hier schnell was erleben und an Erfahrung gewinnen!\n\nSprecht noch einmal mit mir! Ich habe da ein paar Aufgaben, die ich gerne mit Euch besprechen würde....", sourceObjectiveStatus = "unverified-source-field" }
quests[7122] = { id = 7122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mine erobern", description = "In den Minen des Alteractals ist noch weit mehr zu finden als bloßes Erz. Sowohl die Frostwölfe, als auch die Sturmlanzen, haben große Mengen ihrer Ausrüstung in der Eisenschacht- und der Eisbeißermine untergebracht... was eigentlich keine schlechte Idee ist, solange wir die Kontrolle über sie behalten!\n\nBesetzt eine Mine und kehrt zu mir zurück! Um eine Mine zu erobern, betretet eine vom Feind kontrollierte Mine und tötet den dortigen Anführer. Nachdem Ihr das getan habt, gehört die Mine uns und wir werden Truppen zu ihrem Schutz entsenden!", sourceObjective = "Erobert eine Mine, die die Sturmlanzen noch nicht kontrollieren, und kehrt dann zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück.", completion = "Ihr habt es geschafft! Gut gemacht, {name}!\n\nWenn wir erstmal eine Mine kontrollieren und dort Truppen stationiert haben, wird es viel einfacher die dortige Ausrüstung und Mineralien einzusammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[7123] = { id = 7123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit unserem Rüstmeister", description = "{name}, der Rüstmeister der Frostwölfe sucht nach Lehrlingen für Aufgaben, die in die Minen des Tals von Alterac führen. Sprecht mit ihm; er wird Euch mehr berichten.\n\nFolgt der Straße westlich in den Bunker, dann nehmt den westlichen Ausgang und Ihr findet unseren Rüstmeister.", sourceObjective = "Sprecht mit dem Rüstmeister der Frostwölfe.", completion = "Seid gegrüßt, {name}! Es ist immer wieder eine Freude, einen {class} wie Euch zu treffen, der bereit ist, seinen Beitrag für die Horde zu leisten. Sprecht also noch einmal mit mir. Ich habe äußerst wichtige Aufgaben für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[7124] = { id = 7124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mine erobern", description = "So wie Kämpfe im Gebiet des Alteractals wüten, so wüten sie auch durch die Eisbeißer- und Eisenschachtminen. Beide bedeuten enorme Ressourcen an Mineralien und beide werden als Lager genutzt; daher ist es kein Wunder, dass sie so heiß begehrt sind!\n\nHelft uns in der Schlacht, {name}! Erobert für die Horde eine Mine! Begebt Euch zu einer Mine, die noch nicht von uns kontrolliert wird und tötet den dortigen Anführer! Sobald Ihr das geschafft habt, schicken wir Truppen aus, um die Mine zu bewachen!", sourceObjective = "Erobert eine Mine und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück.", completion = "Ihr habt eine Mine erobert! Jetzt wo unsere Krieger die Mine vor Angriffen beschützen, wird es uns viel leichter fallen dort Mineralien abzubauen und die dort eingelagerten Vorräte zu bergen.\n\nHervorragende Arbeit, {name}. Diese Tat ist ein großer Gewinn für unsere Kriegsanstrengungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7141] = { id = 7141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Alterac", description = "Die Forscherliga glaubt, dass es im Alteractal einige Artefakte von Interesse gibt. Allerdings werden uns die Orcs des Frostwolfklans wohl kaum danach forschen lassen. Wir können es der Horde jedoch nicht erlauben, unseren Forschungsbemühungen im Weg zu stehen! Vernichtet den General der Frostwölfe, Drek'Thar. Mit seinem Tod werden die Orcs ihren Vorteil verlieren.\n\nDrek'Thar hält sich in der Burg Frostwolf auf, im Süden des Alteractals. Bezwingt ihn und kehrt dann zu mir zurück.", sourceObjective = "Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Steinhauer im Alteracgebirge zurück.", completion = "Gut gemacht, {name}! Jetzt wo die Horde sich mit den Tod Ihres Generals eine blutige Nase geholt hat, haben wir die Atempause, die wir für unsere Forschungsarbeiten brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7142] = { id = 7142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht ums Alteractal", description = "Die Sturmlanzenzwerge und ihre Verbündeten sind in das Alteractal eingefallen und wir müssen sie vertreiben! Um die Schlacht ums Alteractal gewinnen zu können, müssen wir ihren General töten, Vanndar Sturmlanze!\n\nIhr werdet Vanndar in Dun Baldar, im Norden des Alteractals finden.\n\nTötet ihn, {name}, und kehrt dann zu mir zurück.", sourceObjective = "Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Sturmlanze. Kehrt anschließend zu Voggah Todesgriff im Alteracgebirge zurück.", completion = "Gute Arbeit, {name}! Die Stormpikes haben ihre närrische Invasion bereits verloren.\n\nHah! Das Einzige was sie bisher erreicht haben, ist ihr toter General!", sourceObjectiveStatus = "unverified-source-field" }
quests[7161] = { id = 7161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaggenjagd", description = "Seid gegrüßt, {class}. Es scheint eine Ewigkeit her, seit wir zuletzt dem Ruf des Krieges gefolgt sind. Die alten Gefühle erwachen nur langsam. Doch sind sie erst einmal erwacht, beginnt das Blut erneut zu kochen. Die Kampfeslust kehrt zurück...\n\nAlle Neuankömmlinge im Tal müssen sich zuerst dem Ritus des Kampfes unterziehen.\n\nTief in der nahegelegenen Höhle der Wildpfoten findet Ihr ein Banner der Frostwölfe. Zieht los und holt es für uns zurück. Bringt es zu mir und ich gewähre Euch das Abzeichen eines Initianden der Frostwölfe.", sourceObjective = "Begebt Euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt im Alteractal und findet das Banner der Frostwölfe. Bringt anschließend Kriegsmeister Laggrond das Banner.", progress = "Wacht auf! Wacht endlich auf, {name}! Dies ist kein Traum. Ihr befindet euch tatsächlich inmitten einer tobenden Schlacht!", completion = "Das brennende Gefühl in Euch ist Eure Seele, die langsam erwacht! Euer Geist hat den Ruf zu den Waffen akzeptiert!\n\nIhr gehört nun zu den Frostwolf, {name}. Ich gratuliere.\n\nTragt dieses Abzeichen immer bei Euch. Mit der Zeit werdet Ihr in den Rängen der Frostwolf aufsteigen und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht wird man Euch eines Tages, innerhalb des Frostwolfklans mit Ehrfurcht begegnen. Sollte dieser Tag jemals kommen, werdet Ihr möglicherweise sogar das Auge der Führung erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[7162] = { id = 7162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaggenjagd", description = "Ihr seid genau zur rechten Zeit eingetroffen, {class}. Diese Wilden der Frostwölfe wollen einfach nicht aufgeben! Wir müssen ihnen die Macht der Sturmlanzen vor Augen führen! Am Ende müssen sie sich unserer Überlegenheit beugen.\n\nDoch bevor Ihr Euch auf das Schlachtfeld begebt, solltet Ihr den Reihen der Sturmlanzen beitreten.\n\nSüdwestlich von Dun Baldar befinden sich die Eisschwingenhöhlen. Tief in ihrem Inneren werdet Ihr ein Banner der Sturmlanzen finden. Begebt Euch dorthin und holt das Banner zurück. Bringt es anschließend zu mir und ich werde Euch mit dem Abzeichen eines Initianden der Sturmlanzen auszeichnen.", sourceObjective = "Begebt Euch in die Eisschwingenhöhle südwestlich von Dun Baldar im Alteractal und findet das Banner der Sturmlanzen. Bringt anschließend Leutnant Haggerdin im Alteracgebirge das Banner.", progress = "Hütet Euch vor den Harpyien in der Gegend, {class}. Die werden nicht zögern Euch die Kehle herauszureissen!", completion = "Nehmt dieses Abzeichen und tragt es mit Stolz, {name}. Mit der Zeit werdet Ihr in den Rängen der Stormpikegarde aufsteigen. Kehrt dann zu mir zurück und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht werdet Ihr eines Tages zu einer Legende dieses Schlachtfeldes heranwachsen. Sollte dieser Tag jemals kommen, wird man Euch mit Sicherheit das Auge der Führung verleihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7163] = { id = 7163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg und Anerkennung", progress = "<Kriegsmeister Laggrond salutiert vor Euch.>\n\nJetzt ist eure Zeit gekommen, {name}. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen. \n\nGut gemacht! Zeigt mir Euer Abzeichen!", completion = "Dieses neue Abzeichen zeigt Euren Rang bei den Frostwolf. Tragt es immer bei Euch\n\nUnd {class}... Sterbt mit Ehre." }
quests[7164] = { id = 7164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre innerhalb des Klans", progress = "Es ist gut, Euch wiederzusehen, {class}. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.\n\nWieder ist eure Zeit gekommen, {name}. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.\n\nZeigt mir euer Abzeichen!", completion = "<Kriegsmeister Laggrond salutiert.>\n\nGeht, {name}! Setzt Eure Verteidigung der Frostwolf fort. Dieser Krieg muss gewonnen werden! Für Drek'Thar! Für den Kriegshäuptling!" }
quests[7165] = { id = 7165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdiente Ehrerbietung", progress = "So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..\n\nZeigt mir euer Abzeichen!", completion = "<Kriegsmeister Laggrond Brüllt.>\n\nSie haben schon angefangen, Geschichten über Eure Taten zu erzählen, Soldat. Die Stormpikes zittern vor Angst, wenn man euren Namen ausspricht. Weiter so!" }
quests[7166] = { id = 7166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Helden", progress = "Ihr strahlt Macht und Befehlsgewalt aus, {class}. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.\n\nErhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!\n\nZeigt mir euer Abzeichen!", completion = "Schon bald wird das ganze Schlachtfeld unter eurem wachsamen Auge liegen. Die Führung über das Tal und seine Truppen wird Euer sein!" }
quests[7167] = { id = 7167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge der Führung", progress = "Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.\n\nIhr habt Euch das Auge der Führung redlich verdient.\n\nPräsentiert Eure Abzeichen, Kommandant {name}.", completion = "Sammelt die Kraft dieser Auszeichnung. Lasst unsere Feinde Eure Worte hören. Die Macht der Horde ist und bleibt unantastbar!" }
quests[7168] = { id = 7168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg und Anerkennung", progress = "Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, {class}. Die Zeit ist da!\n\nPräsentiert Euer Abzeichen!", completion = "Lasst unsere Feinde sehen, dass ein angesehener Soldat sie besiegt hat! Kämpft für den Ruhm der Stormpike!" }
quests[7169] = { id = 7169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre innerhalb der Garde", progress = "Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdient\n\nPräsentiert Euer Abzeichen!", completion = "Der König hat von Euren Heldentaten an der Frontlinie gehört, {class}. Macht weiter so in Eurer wackeren Verteidigung der Stormpikegarde!" }
quests[7170] = { id = 7170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdiente Ehrerbietung", progress = "Ich muss es wissen, {name}. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!\n\nIhr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!", completion = "Als wir uns zum ersten Mal trafen hätte ich nie geahnt, dass ein werdender Held vor mir steht. Weiter so, Soldat!" }
quests[7171] = { id = 7171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Helden", progress = "Vor mir steht ein erhabener Held der Allianz.\n\n<Lieutenant Haggerdin salutiert.>\n\nWenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!\n\nPräsentiert Euer Abzeichen!", completion = "Sicherlich werdet Ihr es sein, der das Auge der Führung trägt!" }
quests[7172] = { id = 7172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge der Führung", progress = "Lasst sie Eure Stimme hören, Kommandant {name}! Lasst Sie wissen was Angst bedeutet. Zeigt dem Gegner, über welche Macht die Sturmlanzen in ihren Reihen verfügen!\n\nPräsentiert Euer Abzeichen.", completion = "Ihr seid der Richtige, um unsere Truppen zum Sieg zu führen, Kommandant! Die Soldaten stehen nun unter Eurem Kommando. Sie werden Euren direkten Befehlen Folge leisten. Führt sie an... Vernichtet die Frostwölfe." }
quests[7181] = { id = 7181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Korrak", description = "Die angreifenden Sturmlanzen sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.\n\nAngeführt werden sie von Korrak dem Blutrünstigen - einem grausamen und verschlagenen Biest.\n\nEin Streich gegen Korrak könnte sich als vernichtender Schlag für den Winteraxklan erweisen. Tötet diesen Bastard und Ihr werdet entlohnt.", sourceObjective = "Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.\n\nSolltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Kriegsmeister Laggrond im Alteracgebirge zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7201] = { id = 7201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Element", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, {name}.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", sourceObjective = "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat.", progress = "<Sie reibt sich die Hände.>\n\nZeigt sie mir!", completion = "Großartig! Ich werde das sofort mit einem Kurier nach Undercity schicken lassen.\n\nUnd was Euch angeht: Hier ist die versprochene Bezahlung. Behaltet den Rest, dreckige Bestie!", sourceObjectiveStatus = "unverified-source-field" }
quests[7202] = { id = 7202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrak der Blutrünstige", description = "Die eingeborenen Winteraxtrolle dieser Region sind unbarmherzige Wilde, die nichts lieber täten, als unsere Knochen in einer ihrer widerlichen Mahlzeiten zu sehen.\n\nWir müssen ihnen unsere Macht vor Augen führen!\n\nWir konnten einige Schriftstücke aus ihren Höhlen entwenden, die Aufzeichnungen über ihre Führungshierarchie enthalten. Diese Schriftstücke lassen vermuten, dass ihr Anführer, Korrak der Blutrünstige, sich solange versteckt hält, bis er einen Grund hat sich zu zeigen.\n\nDer Tod Korraks, würde den Tod des Winteraxklans bedeuten! Tötet ihn und kehrt zu mir zurück.", sourceObjective = "Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.\n\nSolltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Leutnant Haggerdin im Alteracgebirge zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7221] = { id = 7221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Ausgrabungsleiter Steinhauer", description = "Ah, {name}, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Sturmlanzen können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Steinhauer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für <einen hart arbeitenden/eine hart arbeitende:c> {class} gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.", sourceObjective = "Sprecht mit Ausgrabungsleiter Steinhauer in der Garnison von Dun Baldar.", sourceObjectiveStatus = "unverified-source-field" }
quests[7222] = { id = 7222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Voggah Todesgriff", description = "Ah, <ein/eine:c> {class}! Wir sind alle hoch erfreut, Euch hier in Alterac anzutreffen, {name}. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Todesgriff. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.", sourceObjective = "Sprecht mit Voggah in Burg Frostwolf.", sourceObjectiveStatus = "unverified-source-field" }
quests[7223] = { id = 7223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungsfetzen", description = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Eisenschmiede bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann unterstützt unsere Kriegsbemühungen und bringt mir diese Stücke!", sourceObjective = "Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen.", progress = "Habt ihr mir Rüstungsfetzen mitgebracht, {name}?", completion = "Das sind ein paar recht gute Stücke, {name}. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", sourceObjectiveStatus = "unverified-source-field" }
quests[7224] = { id = 7224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutezug im Feindesland", description = "Wenn Ihr gegen den Feind kämpft, sammelt die Fetzen seiner Rüstungen ein und bringt sie zu mir. Aus den Fetzen werde ich neue Rüstungen für unsere eigenen Truppen herstellen!", sourceObjective = "Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe.", progress = "Wie läuft die Jagd, {name}.  Habt Ihr irgendwelche Rüstungsfetzen für mich?", completion = "Die werden ihren Zweck erfüllen. Ich werde sie einschmelzen und reparieren und niemand wird je merken, dass sie von diesen feigen Stormpikes stammen!\n\nDanke, {name}. Und lasst mich Eure Rüstung aufbessern...", sourceObjectiveStatus = "unverified-source-field" }
quests[7241] = { id = 7241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Frostwölfe", description = "In der Ferne kann man den Klang der Kriegstrommeln vernehmen, {class}. Die ehrlose Sturmlanzengarde aus Eisenschmiede greift den Klan Eures Kriegshäuptlings an.\n\nIhr seid kampfgestählt, das verrät mir Euer Auftreten. Es scheint, dass Ihr wahrlich bereit seid, der Sache des Frostwolfklans zu dienen.\n\nEs liegt nun an Euch, den nächsten Schritt in Eurer Entwicklung zu gehen.\n\nNördlich von Tarrens Mühle, im Alteracgebirge, befindet sich der Zugang zum Alteractal. Betretet das Tal und sucht Kriegsmeister Laggrond auf. Beeilung {class}, die Schlacht hat bereits begonnen!", sourceObjective = "Reist ins Alteractal, das sich im gleichnamigen Gebirge befindet. Sucht dort außerhalb des Tunneleingangs Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe. Das Alteractal findet Ihr nördlich von Tarrens Mühle am Fuß des Alteracgebirges.", completion = "Um ein Soldat der Frostwolf zu werden, muss man sich erst beweisen...", sourceObjectiveStatus = "unverified-source-field" }
quests[7261] = { id = 7261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die hoheitliche Anordnung", description = "Wir kämpfen eine blutige Schlacht in den Tälern von Alterac. Der barbarische Frostwolfklan fordert die Sturmlanzen zum Kampf heraus! Sie müssen im Namen unseres König Magni Bronzebart ausgelöscht werden! Die Eroberung und Säuberung dieses Landes ist eine herrschende und territoriale Notwendigkeit für das Königreich von Eisenschmiede.\n\nLeider wachsen gute Soldaten nicht auf Bäumen! Meldet Euch bei Leutnant Haggerdin im Alteractal, um Euren ehrenvollen Pflichten bei den Sturmlanzen nachzukommen.", sourceObjective = "Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.\n\nFür den Ruhm von Bronzebart!", completion = "An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[7281] = { id = 7281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderliebe", description = "Welch tragische Fügung... Mein Bruder steht mir auf dem Schlachtfeld gegenüber: Er ist einer der Kommandanten der Sturmlanzen.\n\nVon allen vier Kommandanten stellt er zweifellos die größte Gefahr dar. Falls man ihn tötet, würde die Bansheekönigin ihn vielleicht wiedererwecken, so wie sie es mit mir getan hat - und ihm die Irrtümer seines bisherigen Handelns vor Augen führen...\n\nTief im feindlichen Gebiet werdet Ihr meinen Bruder finden. Tötet ihn und bringt ihn zu mir zurück. Ich vertraue darauf, dass Ihr diese Mission erfolgreich zu Ende bringt, Soldat. \n\nUnd Soldat... geht nicht alleine.", sourceObjective = "Begebt Euch ins Gebiet der Sturmlanzen und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", completion = "Eure Heldentat wird nicht unbemerkt bleiben, {name}.\n\n Ich darf keine Zeit verlieren, wenn er gerettet werden soll. Sylvanas muss kontaktiert werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[7282] = { id = 7282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderliebe", description = "Er muss aus seinem Elend befreit werden, Soldat! Mein Bruder weiß nicht mehr, was er tut. Er ist nur noch eine willenlose Marionette der grausamen Bansheekönigin.\n\nBegebt Euch, über das Feld des Kampfes, in die Tiefen des Gebiets der Frostwölfe. Findet meinen Bruder und zerstört, was von ihm übrig ist. Seine Qualen sollen endlich ein Ende haben.", sourceObjective = "Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", completion = "Ihr habt doch daran gedacht den Leichnam zu verbrennen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[7301] = { id = 7301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Himmelsstürmer", description = "Wir konnten sie gefangennehmen, {race}. Ich rede von ihren Schwadronskommandanten. Es war eine wilde Himmelsschlacht, doch letztendlich haben wir sie geschlagen! Sie fielen wie Steine vom Himmel! Leider hat es auch viele unserer besten Piloten erwischt, als Sie die Burg Frostwolf angriffen. Ihr müsst herausfinden was aus ihnen geworden ist.\n\nDurchkämmt das Gebiet der Westturmstellung und Burg Frostwolf. Dort wurden Sie das letzte Mal gesehen. Und geht gründlich vor!", sourceObjective = "Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.", completion = "Unglaublich! Ihr habt Sie doch befreit oder? Oder??? Nun gut, immerhin kennen wir jetzt ihren Aufenthaltsort.", sourceObjectiveStatus = "unverified-source-field" }
quests[7302] = { id = 7302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Himmelsstürmer", description = "Unsere Luftunterstützung musste einen schweren Schlag hinnehmen, {name}. Sämtliche Schwadronskommandanten wurden über feindlichem Gebiet abgeschossen. Ihr müsst herausfinden, was aus ihnen geworden ist, sodass wir einen Rettungsversuch unternehmen können!\n\nGuse wurde das letzte Mal gesehen, als sie über den Eisschwingenbunker hinwegflog. Jetzors Reittier wurde zuletzt am Sägewerk der Sturmlanzen gesichtet. Mulverick... dieser waghalsige Narr, stürzte in der Nähe des Nordbunkers von Dun Baldar ab.\n\nDas sind alle Informationen, die ich habe. Schwärmt aus und durchsucht das Gebiet gründlich!", sourceObjective = "Findet heraus, was aus Schwadronskommandantin Guse, Schwadronskommandantin Jeztor und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück.", completion = "Gut gemacht! Eure Informationen sind von umschätzbarem Wert für unsere Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[7321] = { id = 7321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milde Schildkrötensuppe", description = "Wer sagt denn, dass Untote keine Ahnung vom Kochen haben? Nehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von den Toten zurückgekehrt sind, nur um eine Schüssel voll davon zu kosten.\n\nDa wir gerade davon sprechen: In letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis zum Lordameresee gereist, um Schnappkiefer zu jagen, aber meine Arbeit hier beschäftigt mich mittlerweile einfach zu sehr.\n\nWenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern bringt, dann werd ich Euch in das Geheimnis meines Rezepts einweihen!", sourceObjective = "Bringt 10 Stücke Schildkrötenfleisch zu Christoph Jeffkott in Tarrens Mühle.", progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Meine milde Schildkrötensuppe wird Euch in einer kalten Nacht warm halten... falls es Euch überhaupt interessiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[7341] = { id = 7341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gerechter Handel", progress = "Seid gegrüßt, {race}. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt. \n\nAuf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!\n\nIch schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?", completion = "Excellent! Ich bin ein Tauren, der sein Wort hält, {race}. Die Pfeile gehören Euch." }
quests[7342] = { id = 7342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeile sind was für Memmen", progress = "Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?\n\nIch sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?", completion = "Abmachung ist Abmachung! Die Pfeile gehören Euch." }
quests[7367] = { id = 7367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefahr bannen", description = "Die Frostwölfe haben ihre Frontlinien und Basen allesamt vermint, {class}. Achtet darauf wohin Ihr tretet, wenn Ihr in feindliches Territorium eindringt.\n\nWenn wir dem Feind einen entscheidenden Schlag versetzten wollen, müsst Ihr seine Quelle für Sprengwaffen zum Versiegen bringen - Ich rede vom feindlichen Sprengmeister! Tötet ihn und wir können alle Minen sicher entschärfen. Solange er ausfällt, fallen auch seine Minen aus.\n\nVermutlich befindet er sich in einem Turm, nahe der Eisblutgarnison. Viel Glück, Soldat!", sourceObjective = "Findet den Sprengmeister der Frostwölfe und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Sturmlanzen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7368] = { id = 7368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefahr bannen", description = "Ich weiß alles über Landminen. Immerhin habe ich alle Minen an unseren Frontlinien selbst verlegt.\n\nWenn Ihr das Minenfeld der Sturmlanzen unschädlich machen wollt, braucht Ihr nur eines zu tun - Tötet den feindlichen Sprengmeister! Zweifellos versteckt sich der feige Zwerg im ersten Turm, auf dem Feld des Kampfes. Schaltet ihn aus und die Landminen werden nicht zurückkommen, nachdem sie von Euch entschärft wurden.\n\nFalls Ihr es schaffen solltet den Sprengmeister zu töten, kommt zu mir zurück und lasst es mich wissen. Keine gute Tat soll unbelohnt bleiben.", sourceObjective = "Findet den Sprengmeister der Sturmlanzen und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwölfe zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7383] = { id = 7383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Die Bürde der Kaldorei", description = "Ihr müsst nun den Mondbrunnen unter den Ästen des Orakelbaums im fernen Nordwesten aufsuchen. Er ist der erste und mächtigste unserer Brunnen und es heißt von seinem Wasser, es enthalte die Essenz von Elunes Macht.\n\nEntnehmt eine Phiole des Wassers und kehrt zu mir zurück. Ich werde euch an der Weggabelung vor Darnassus treffen, wenn Eure Aufgabe vollendet ist.", sourceObjective = "Füllt die Amethystphiole.", progress = "Die Druiden, unter Mitwirkung des Orakelbaums und des Erzdruiden, haben sich sorgsam um die Hege Teldrassils gekümmert. Wir haben jetzt zwar eine neue Heimat, doch unsere Unsterblichkeit haben wir noch nicht wiedererlangt.", completion = "In der Nähe des Orakelbaums... kann man fast spüren, wie die Weisheit Gestalt annimmt. Lasst mich mit der Geschichte fortfahren...\n\nTeldrassil wuchs und gedieh, und der Erzdruide wandte sich an die Großdrachen, um deren Segen zu erhalten, den sie in längst vergangenen Zeiten über Nordrassil verbreitet hatten. Nozdormu jedoch, der Lord der Zeit, weigerte sich, seinen Segen zu spenden und tadelte den Druiden wegen seiner Arroganz. Einig mit Nozdormu widersetzte sich auch Alexstrasza Staghelm und ohne ihren Segen entartete Teldrassil und wuchs auf unvorhersehbare Weise...", sourceObjectiveStatus = "unverified-source-field" }
quests[7385] = { id = 7385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gallone Blut", progress = "Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, {name}.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord erscheinen und diesen Hunden von den Stormpike den ganzen Zorn des Frostwolfklans vor Augen führen!" }
quests[7386] = { id = 7386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haufenweise Kristalle", progress = "Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.\n\nDer Zirkel wäre hocherfreut über derartige Spenden, {name}.", completion = "Gut gemacht, {name}. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen." }
quests[7429] = { id = 7429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Knot!", progress = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", completion = "Vielen Dank, dass Ihr mich befreit habt! Ihr seid meine Nummer eins.\n\n Ich hab's doch gewusst, dass ich mein Leben nicht als Ogerhappen beende!" }
quests[7441] = { id = 7441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin und der Älteste Azj'Tordin", description = "Ich habe nur einen Moment nicht aufgepasst, Fremder. In meiner Eile, dem Griff des gefallenen Prinzen zu entkommen, wurde ich ausgeraubt. Ein besonders widerlicher Dämon, namens Pusillin, stahl mir mein Buch der Zauberformeln und den Schlüssel zu den einstmals großen Hallen von Eldre'Thalas.\n\nMein Interesse am Schlüssel ist verloschen als ich meine Unsterblichkeit gegen die Freiheit eingetauscht habe. Doch ich benötige unbedingt mein Buch der Zauberformeln.\n\nFindet den Dämon Pusillin und bringt mir mein Buch.\n\nSucht Pusillin im Wucherborkenviertel von Düsterbruch.", sourceObjective = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\n\nKehrt mit dem Buch zu Az'Tordin, beim Larisspavillon in Feralas, zurück.", progress = "Ich bereue nichts, Fremder. Die Königin ist schon lange tot. Die Arbeiten der Shen'dralar sind seit langem durch Prinz Tortheldrins Wahnsinn zerstört worden. Ich suche nur noch die Freiheit... Flucht...", completion = "Ihr habt es gefunden! Ich verfluche diesen verdammten Dämonen. Leider sind meine Vorräte fast aufgebraucht. Doch sucht Euch nur etwas von meinen Sachen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[7461] = { id = 7461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der innere Wahnsinn", description = "Habt Ihr genug gehört? Seid Ihr <ein Mann/eine Frau> der Tat?\n\nDieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Habt Ihr das erst einmal geschafft, könnt Ihr Immol'thar vernichten. Die Macht des Prinzen wird stark geschwächt sein, greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer.", sourceObjective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", progress = "Seid wachsam Abenteurer. Der Prinz ist... überzeugend.", completion = "Ihr seid ein Held, wir sind Euch zu ewigen Dank verpflichtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[7462] = { id = 7462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[7463] = { id = 7463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Erfrischung", description = "<Ein/Eine:r> {race} und dazu noch <Magier/Magierin>! Wie wunderbar. Ich habe jemanden wie Euch schon seit... wie lange ist es nun schon her?... 500 Jahren nicht mehr gesehen!\n\nIch habe da etwas, das Euren Durst zu löschen vermag, doch zuerst müsst Ihr etwas für mich erledigen.\n\n<Lydros kichert.>\n\nEs gibt eine Anomalie in Eldre'Thalas. Ein Wasserelementar hat sich im östlichen Flügel niedergelassen. Seine Anwesenheit muss unbedingt katalogisiert werden!\n\nReist nach Düsterbruch in das Wucherborkenviertel und sammelt etwas von der elementaren Essenz der Hydrobrut. Bringt Sie anschließend zu mir zurück und ich werde Euch einen äußerst nützlichen Zauberspruch beibringen.", sourceObjective = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz zum Wissenshüter Lydros im Athenaeum zurück.", progress = "Ja bitte? Kennen wir uns?", completion = "Wundervoll!...Wer wart Ihr doch gleich nochmal? Ach, ist auch egal. Hmm... Ihr seid ein {class}, also werdet Ihr das hier vielleicht nützlich finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7481] = { id = 7481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elfische Legenden", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Traumsucher der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", sourceObjective = "Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache.", completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[7482] = { id = 7482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elfische Legenden", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Traumsucher der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", sourceObjective = "Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei der Gelehrten Runendorn in der Mondfederfeste.", completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[7483] = { id = 7483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband der Schnelligkeit", description = "Meister Traumsucher verlor den Buchband der Schnelligkeit im Ostflügel. Mit dem Buchband kann ein Zauber der geringen Hast auf Eure Ausrüstung gewirkt werden. Ein einfacher Trick...\n\nWie auch immer... Falls Ihr Interesse habt, bringt mir den Buchband und einige grundlegende Reagenzien.\n\nHrm... Ich glaube man benötigt das Blut von Helden, einen makellosen schwarzen Diamanten und große glänzende Splitter. Ich mag mich natürlich Irren...\n\n<Lydros zuckt mit den Achseln.>", sourceObjective = "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2-mal das Blut von Helden, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.", progress = "Was gibt es? Seht Ihr nicht, dass ich arbeite!", completion = "<Lydros gähnt.>\n\nWie versprochen, das Arkanum der Schnelligkeit. Verbraucht nicht gleich alles auf einmal.\n\n<Lydros kichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[7484] = { id = 7484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband des Fokus", description = "Dieser Buchband erweckte die Neugierde eines jungen Familiars, welcher einem der Hüter gehörte. Das arme Ding wurde nur ein paar Wochen alt\n\nDiejenigen unter Euch, die sich mit Magie beschäftigen, dürften dieser Gegenstand interessieren.\n\nDas Buchband des Fokus ging in diesem Flügel verloren. Ich kann nur annehmen, dass einer der Geister der Hochgeborenen es in Besitz genommen hat.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und etwas Schattenhaut, und ich werde das Arkanum herbeizaubern.", sourceObjective = "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2-mal Schattenhaut, zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.", progress = "Ihr nun wieder? Was könntet Ihr jetzt schon wieder wollen?", completion = "Achtet darauf, Euch während der Verzauberung nicht selbst weh zu tun, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[7485] = { id = 7485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchband des Schutzes", description = "Als er von dem Verlust dieses Buchbands hörte, weinte er wie ein kleines Kind. Wohlgemerkt, Ich selbst habe schon über derartige Verluste getrauert - und kein Verlust wiegt mehr, als der Verlust von Wissen und Geschichte- aber wegen diesem Haufen nutzloser Zauberformeln? Lächerlich! Mir scheint, der Prinz hat ihm wohl einen Gefallen getan, als er ihm das Fleisch von den Knochen riss.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und eine ausgefranste Monstrositätenstickerei, und ich werde das Arkanum wiederherstellen.\n\nAch ja, sucht im Nordflügel.", sourceObjective = "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Wissenshüter Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.", progress = "Meine Geduld, verhindert euer Leiden.", completion = "Ja, ja... Beruhigt Euch wieder. Wie versprochen, ist hier Euer Arkanum.", sourceObjectiveStatus = "unverified-source-field" }
quests[7486] = { id = 7486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belohnung eines Helden", description = "{name}, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben.\n\nWir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall...ist eine Belohnung mehr als angebracht.\n\nUnter der Brandung an der südlichen Basis der Insel, findet Ihr einen Kasten. In diesem werdet Ihr Eure... Belohnung finden.\n\nGeht, {name}. Nehmt Euch Eure Belohnung.", sourceObjective = "Nehmt Eure Belohnung aus Hydraxis' Kasten.", completion = "Hydraxis Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, {name}. Möge es Euch vor den Feinden des Wasserlords schützen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[7487] = { id = 7487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung mit dem Kern", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, {race}. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Schwarzfels führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Schwarzfelstiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", sourceObjective = "Begebt Euch zum Portal in den Schwarzfelstiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter am Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7488] = { id = 7488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris' Netz", description = "Die Magierin Lethtendris, eine bösartige Blutelfe, deren Brutalität nur durch ihre pervertiere Hingabe zur Magie in den Schatten gestellt wird, ist nach Düsterbruch geflüchtet. Sie hat eine Apparatur entwickelt, ein Netz, um die magischen Energien dieses Ortes einzufangen und wir fürchten, dass wenn Sie niemand aufhält, sie der Welt einen unwiderruflichen Schaden zufügen wird!\n\nStoppt Sie, {name}. Findet Sie und nehmt das Netz an Euch. Am ehesten werdet Ihr sie nahe den Satyrn, im Wucherborkenviertel von Düsterbruch, finden. Bringt das Netz anschließend zu mir und ich werde versuchen, dessen Kräfte wieder der Wildnis zurückzugeben...", sourceObjective = "Bringt Lethtendris' Netz zu Latronicus Mondspeer in der Mondfederfeste in Feralas.", progress = "Habt Ihr das Netz, {name}?  Seine konzentrierten magischen Energien müssen wieder freigelassen werden!", completion = "Ihr habt also das Netz!  Hervorragende Arbeit, {name}!  Lethtendris ist, genau wie viele andere ihrer Art, blind für die Gefahren, die der Missbrauch von Magie unserer Welt hinzufügen kann. Sie alle halten sich für Meister der Magie und dabei bemerken sie nicht, wie sie zum Sklaven ihrer eigenen Hingabe werden. Ihr Tod erfüllt mich mit Trauer, aber er war notwendig.\n\nDanke,  {name}. Ich werde die Energien des Netzes sicher über ein größeres Gebiet freilassen und es anschließend zerstören, um den weiteren Missbrauch seiner Kräfte zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[7489] = { id = 7489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris' Netz", description = "Die Blutelfe Lethtendris hat ihre Grenzen überschritten. So versessen war sie darauf magische Macht zu erlangen, das sie ihre Brüder verraten und eine teuflische Apparatur gebaut hat, ein Netz welches in der Lage ist, die verdorbenen magischen Energien von Düsterbruch einzufangen. Selbst jetzt sammelt sie diese Energien und plant, sie gegen ihre Feinde einzusetzen. \n\nLethtendris muss aufgehalten werden. Sucht sie im Wucherborkenviertel von Düsterbruch, besiegt sie und bringt anschließend ihr Netz zu mir. So kann es vielleicht wieder in die Hände einiger Blutelfen übergeben werden, die dieses Artefakt mit klarem Verstand untersuchen können.", sourceObjective = "Bringt Lethtendris' Netz zu Talo Dornhuf im Camp Mojache in Feralas.", progress = "{name}, habt Ihr Lethtendris' Netz?", completion = "Das habt Ihr gut gemacht, {name}. Dieses Netz enthält in seinem Inneren einen riesigen Vorrat der Magie von Düsterbruch, und ich fürchte um den Schaden, der von jemanden so unverantwortlichen wie Lethtendris angerichtet werden könnte. Ihr Tod erfüllt mich mit Trauer, aber ich weiß, dass sie sich solange sie am Leben war nie freiwillig von ihrem Netz getrennt hätte.\n\nVielen Dank, {name}. Ich werde das Netz an einige weitaus verantwortungsbewusstere Schüler der Magie übergeben. Sie werden die neuen Wächter seiner Magie sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[7490] = { id = 7490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg für die Horde", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn Eurem Kriegshäuptling.", sourceObjective = "Bringt Onyxias Kopf zu Garrosh in Orgrimmar.", progress = "<Thralls stoische Mine verschwindet für den Bruchteil einer Sekunde, als er den riesigen Kopf von Onyxia erblickt. Beinahe hätte er den mächtigen Doomhammer gezogen.>", completion = "Dies ist ein großartiger Sieg für die Horde, {name}. So viele male habt Ihr Euren Kriegshäuptling geehrt. Nun ist es an der Zeit, dass der Kriegshäuptling Euch seine Ehre erweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[7491] = { id = 7491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für alle sichtbar", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Der Kriegshäuptling salutiert euch.>\n\nLasst Euer Publikum nicht warten, großer Held.", sourceObjective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", completion = "Wählt Eure Belohnung und lasst die Feierlichkeiten anlässlich Eures großen Sieges beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7492] = { id = 7492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Mojache", description = "Talo Dornhuf, ein Taurenältester in Feralas, hat uns um Hilfe gebeten. Er hat nur wenige Einzelheiten verraten, doch wie es scheint sucht er nach Agenten für eine Angelegenheit, die sowohl heikel als auch dringend ist.\n\nDient der Horde, {name}. Begebt Euch ins Camp Mojache in Feralas und sprecht mit Talo.", sourceObjective = "Sprecht mit Talo Dornhuf in Camp Mojache, in Feralas.", completion = "Ah, es ist freut mich einen {class} zu sehen, der meinem Ruf gefolgt ist. Ich benötige Eure Dienste, {name} und ich befürchte, Sie werden euch auf einen gefährlichen Pfad führen... \n\nEinen Pfad nach Düsterbruch.", sourceObjectiveStatus = "unverified-source-field" }
quests[7493] = { id = 7493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise beginnt erst", sourceObjective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[7494] = { id = 7494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mondfederfeste", description = "{name}! Man braucht Euch in Feralas!\n\nEine abtrünnige Magierin, Lethtendris, ist in die uralten Elfenruinen von Eldre'thalas, vielen bekannt als Düsterbruch, geflohen. Es wird angenommen, dass sie einen gefährlichen Gegenstand voller magischer Energien bei sich trägt, der dringend wiederbeschafft werden muss.\n\nLatronicus Mondspeer hat Agenten angefordert, die in Düsterbruch eindringen und den Gegenstand von Lethtendris zurückholen sollen.\n\nDient der Allianz! Sucht Latronicus in der Mondfederfeste in Feralas auf.", sourceObjective = "Sprecht mit Latronicus Mondspeer in der Mondfederfeste in Feralas.", completion = "Seid gegrüßt, {name}. Ich bin erfreut Euch hier zu sehen. Nur schade, dass unser Treffen unter diesen Umständen stattfindet\n\nHört mir genau zu, ich habe eine Aufgabe von größter Wichtigkeit für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[7495] = { id = 7495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg für die Allianz", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn dem König Varian Wrynn.", sourceObjective = "Bringt Onyxias Kopf zu König Varian Wrynn in Sturmwind.", progress = "Bei Uthers Bart!", completion = "Für so viele Jahre habe ich unter ihrem Bann gestanden. Endlich wurde Gerechtigkeit geübt und die Ehre von Stormwind wieder hergestellt! Heute werden wir diesen glorreichen Sieg feiern!", sourceObjectiveStatus = "unverified-source-field" }
quests[7496] = { id = 7496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Zeiten feiern", description = "Sucht Major Mattingly im Tal der Helden auf, {name}. Er erwartet Euch bereits...", sourceObjective = "Sucht Major Mattingly im Tal der Helden auf.", completion = "Nur wenige wurden bisher mit einer solchen Zeremonie geehrt, {name}. Bitte wählt Eure Belohnung aus, damit wir mit den Feierlichkeiten beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[7497] = { id = 7497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise beginnt erst", sourceObjective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[7498] = { id = 7498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona: Eine Studie über Heimlichkeit und Verrat", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", sourceObjectiveStatus = "unverified-source-field" }
