quests[7507] = { id = 7507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nostro's Compendium", description = "Ihr habt etwas von größter Wichtigkeit entdeckt. Dieses Buch ist anders, als alle anderen die Ihr bisher gesehen habt.\n\nEs scheint, als hätte jemand oder etwas es geschafft, das Siegel des Athenaeums aufzubrechen. Der Text in seinem Inneren ist beschädigt und schwer lesbar.", progress = "Ah, eines unserer wertvollsten Kompendien. Dieses eine wurde schon seit einer Ewigkeit vermisst.", completion = "Auf dem Schwarzmarkt hättet Ihr für dieses Buch eine ganz schöne Menge Gold erhalten, {name}. Insbesondere mit dem gebrochenen Schutzsiegel. Ein jeder mit einer ausreichenden Intelligenz, um das gesammelte Wissen auf diesen heiligen Seiten zu lesen, wäre so in der Lage, die Geheimnisse des Drachentötens zu erlernen.\n\nVielleicht wäre eine großzügige Belohnung angebracht... Nun ja, eine Belohnung, die enorme Anstrengungen erfordert, um Sie zu erhalten." }
quests[7508] = { id = 7508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", progress = "Sehr gut, lasst uns beginnen...", completion = "Solltet Ihr es schaffen in den Hort des Drachen einzudringen, die Klinge unter ihrem feurigen Atem zu erhitzen und sie in ihrem Blut zu härten, werde ich die Klinge für Euch binden." }
quests[7509] = { id = 7509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Quel'Serrar", progress = "Eines Tages wird vielleicht wieder jemand die Prismatische Klinge führen.", completion = "<Lydros murmelt etwas Unverständliches.>\n\nWie versprochen {class}, die Klinge von Quel'Serrar." }
quests[7541] = { id = 7541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst an der Horde", sourceObjective = "Unsere Gelehrten werden einige Zeit brauchen, um den Anhänger, den Ihr uns gebracht habt, zu studieren. Allerdings möchte ich Euch für Euren Dienst an der Horde eine kleine Belohnung geben.\n\nDanke, {name}.  Eure Taten ehren Euch und uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[7562] = { id = 7562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'zul Blutbringer", description = "{name}, Eure Studien der dunklen Künste sind sehr eingehend. Euer Einfluss auf die Kräfte der jenseitigen Welt ist sehr stark geworden... ich denke, Ihr seid nun bereit eines der berüchtigten Schreckensrösser an Euch zu binden.\n\nDas Ritual zum Beschwören eines dieser Biester erfordert große Macht und Ressourcen, doch wenn Ihr solch ein episches Reittier beherrschen wollt, sprecht mit Meister Mor'zul Blutbringer. Er hat sein Lager nahe des Altars der Stürme in der Brennenden Steppe aufgeschlagen.\n\nGeht, {name}. Diese Aufgabe wird sehr gefährlich werden, aber ein Hexenmeister von Eurer Statur sollte sich nicht vor Gefahr fürchten.", sourceObjective = "Sprecht mit Mor'zul Blutbringer beim Altar der Stürme in der Brennenden Steppe.", completion = "Seid gegrüßt, {name}. Seid Ihr wie ich gekommen, um hier am Altar der Stürme zu studieren? Vielleicht um seine Energien für einen geheimen Zweck zu nutzen...\n\nOder seid Ihr vielleicht sogar hier, um mit mir zu sprechen? Ja, ich denke das seid Ihr.\n\nIhr wollt also ein Schreckensross beherrschen? Diese Aufgabe ist nicht einfach. Das wird Euch eine nicht unerhebliche Menge an Blut kosten... und natürlich auch an Gold. Doch ein Schreckensross aus Xoroth ist einen solchen Aufwand mehr als wert. Also wenn Ihr interessiert seid, hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[7563] = { id = 7563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochendes Blut", description = "Die Schreckensrösser existieren auf einer uns fremden Welt, in der feurigen Ebene von Xoroth. Um eines dieser einzigartigen Tiere an Euch zu binden, werdet Ihr mächtige Glyphen beschwören müssen. Ich werde für Euch die erforderlichen Glyphen auf einem Pergament niederschreiben, doch dafür brauche ich eine ganz spezielle Tinte.\n\nIm weit entfernten Winterquell lebt eine besondere Eulenart. Einst waren es normale Tiere, doch die dämonische Macht der Flüsternden Schlucht trieb sie in den Wahnsinn. Übrig blieben nur Blutrünstige Bestien.\n\nEs ist ihr Blut, das ich zum Zeichnen der Glyphen benötige. Bringt mir etwas davon und ich kann Euch weiterhelfen.", sourceObjective = "Mor'zul Blutbringer in der Brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt.", progress = "Habt Ihr die tobenden Eulenbestien gefunden, {name}? Die Magie dieser Kreaturen ist sehr stark und konzentriert sich besonders im Blut dieser verzerrten Wesen.", completion = "Ausgezeichnet! Ich werde das Blut mit Tinte abmischen und es für die Schriftrolle verwenden, die ich Euch versprochen habe. Vielleicht werde ich ein wenig davon für mich zurückbehalten, denn wie ich hörte, ist der Geschmack des Blutes sehr belebend...", sourceObjectiveStatus = "unverified-source-field" }
quests[7564] = { id = 7564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildaug", description = "Mein Assistent Gorzeeki ist ein recht bewanderter Alchemist. Er sollte in der Lage sein die Tinte herzustellen, die ich für die Herstellung der Schriftrolle benötige. Ich habe das von Euch mitgebrachte Blut destilliert. Nehmt es und bringt es zu Gorzeeki, damit er mit seiner Arbeit beginnen kann.", sourceObjective = "Bringt den Behälter mit Blut zu Gorzeeki Wildaug beim Altar der Stürme in der brennenden Steppe.", progress = "Habt Ihr etwas für mich? Ist es zufällig eine große, saftige Spinne? Nicht oder? Oder vielleicht eine Kakerlake? Ich hoffe, sie ist noch am Leben... ich mag es, auf ihnen herumzukauen, wenn sie noch leben...", completion = "Oh, Blut. Bestimmt von Meister Mor'zul. Er liebt das Zeug und mag es, wenn man es literweise vergießt. Ich hingegen bevorzuge es, wenn es noch durch die Venen eines kleinen Nagetiers jagt. Auf die Art bleibt es warm... bis man es braucht.\n\nDieses Blut ist von großer Macht erfüllt. Mor'zul stellt wohl wieder eine Schriftrolle zur Beschwörung eines Schreckensrosses her. Wie aufregend!\n\nFalls das wahr ist und Ihr das Ritual durchführt, dann... werdet Ihr noch einiges mehr als Blut brauchen, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[7581] = { id = 7581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fundament des Gefängnisses", description = "Ihr müsst ein geeignetes Fundament für das Gefängnis der Verdammniswache finden.\n\nDas Blut der Wildhufsatyrn, die in Düsterbruch hausen, sollte dem Genüge tun. Das geronnene Blut wird die Splitter von Hederine zusammenhalten und das Kristallgefängnis mit Energie versorgen.", sourceObjective = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der Faulenden Narbe zurück.", progress = "Allein das Blut der Wildhufsatyrn wird ausreichend sein.", completion = "Ah, welch' exzellente Ausbeute. Das Blut wird die magische Verteidigung der Verdammniswache  unterdrücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[7582] = { id = 7582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefängnishülle", description = "Die Dämonen von Hederine, die das Vorgebirge des Berges Hyjal bevölkern, sondern mächtige Gifte ab, die mit der Zeit hart und somit zu einem kompakten Anti-Magiekristall werden. Diese Kristalle sind auch als Tränen der Hederine bekannt.\n\nNicht einmal die gewaltige Macht einer Verdammniswache könnte die Wände eines Gefängnisses durchbrechen, die aus diesem Material errichtet wurden.\n\nReist in die Flüsternde Schlucht in Winterquell und holt Euch die Tränen.", sourceObjective = "Reist in die Flüsternde Schlucht in Winterquell und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der Faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt.", progress = "Die Dämonen von Hederine werden Euch ihre wertvollen Steine nicht kampflos überlassen, {name}.", completion = "Ich muss das Blut der Wildhufe lediglich mit diesen Kristallen vereinen, dann sollte das Gefängnis bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[7583] = { id = 7583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterdrückung", description = "Das Gefängnis ist bereit. Jetzt kommen wir zum schwierigsten Teil des Unterfangens.\n\nIhr müsst mithilfe des Kristallgefängnisses einen Verdammniswachenkommandanten in der Faulenden Narbe finden und fangen.\n\nSeid gewarnt! Verdammniswachen sind gerissene und tödliche Gegner, die Euch sofort zu zerstören versuchen werden, sobald Ihr mit dem Ritual der Gefangenschaft beginnt. Euer Gegner wird bei seinem Versuch der Gefangenschaft zu entgehen nichts unversucht lassen.\n\nEr wird sich nur auf Euch konzentrieren, {name}. Ich muss Euch deshalb zu der Begleitung von einigen Gefährten raten, die fähig genug sind, um Euch am Leben zu erhalten!", sourceObjective = "Wagt Euch in die Faulende Narbe heraus und macht einen Verdammniswachenkommandanten ausfindig.\n\nWendet das leuchtende Kristallgefängnis auf den Verdammniswachenkommandanten an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.\n\nSolltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der Faulenden Narbe.", progress = "Hm? Nun?", completion = "Ihr habt meine Anweisungen befolgt. Das Wissen von der Beschwörung und Kontrolle des Biests kann nun endlich an Euch weitergegeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7601] = { id = 7601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibys Anweisungen", description = "Wenn ich Euch das Geheimnis der Beschwörung eines Höllenbestiendieners lehren soll, so müsst Ihr Kroshius zerstören und mir den Höllenbestienkern seiner brennenden Überreste bringen. Wie auch immer, es ist nicht so einfach wie es klingt. Kroshius hat zwar alles, ist aber vollständig ausgebrannt. Ihr müsst seinen Körper wieder entzünden und ihn wieder von dem Schutthaufen auferstehen lassen. Allerdings braucht Ihr dafür ein paar Komponenten von anderen Dämonenwesen.\n\nImpsy, mein Wichtel, soll Euch auf alles weitere vorbereiten.", sourceObjective = "Sprecht mit Impsy im Teufelswald.", completion = "Junge, Junge, jetzt geht's los.", sourceObjectiveStatus = "unverified-source-field" }
quests[7602] = { id = 7602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reine Teufelsessenz", description = "Ihr werdet für die Wiederbelebung von Kroshius Teufelsfeuer benötigen. Ich kann zwar Teufelsfeuer machen, brauche dazu aber ein paar Komponenten.\n\nIhr müsst mir reine Teufelsessenz aus drei bestimmten Gebieten der Welt bringen.\n\nDen ersten Essenztyp findet Ihr bei den Satyrn der Legashi von Azshara; den zweiten Typ bei den Legionären von Jaedenar in Jaedenar und den dritten bei den Wachposten der Teufelswache in den Verwüsteten Landen.\n\nBringt mir jeweils eine Essenz pro Typ, dann werde ich das Teufelsfeuer entfachen, mit dem Ihr Kroshius wieder auferstehen lassen könnt.", sourceObjective = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.\n\nDie Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den Verwüsteten Landen bergen die Teufelsessenz ihrer Region.\n\nFindet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.", progress = "Sagt es keinem, aber Niby ist bescheuert.", completion = "Gebt mir einen Moment, damit ich die drei Essenzen kombinieren und somit das Teufelsfeuer entfachen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[7603] = { id = 7603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroshius Höllenbestienkern", description = "Kroshius liegt zusammengefallen im Narbengrund, Richtung Nordosten. Verwendet dieses Teufelsfeuer auf seinen Überresten, es sollte die gefallene Höllenbestie wieder erwecken.\n\nIch bin überzeugt, dass er Euch und Euren Begleiter genau dann umbringen wird.\n\nSolltet Ihr Kroshius dennoch auf wundersame Weise töten können, dann nehmt den Höllenbestienkern und bringt ihn zu Niby.", sourceObjective = "Sucht im Narbengrund im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.\n\nBringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.", progress = "Habt Ihr Euch verlaufen?", completion = "Geschäft ist Geschäft! Schnell, nehmt dies und schreibt dies nieder. Ich habe keine Zeit! Meine größte Beschwörung steht noch bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[7604] = { id = 7604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbindlicher Vertrag", description = "<Der Unterzeichner/Die Unterzeichnerin> erklärt hiermit, dass es sich bei dem Sulfuronblock, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird, um ein Original und nicht um eine Nachbildung handelt. <Der Unterzeichner/Die Unterzeichnerin> erkennt ebenso an, dass jeglicher Schaden, der <ihm/ihr> in Folge des Versuchs Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen widerfahren könnte, nicht in der Verantwortung oder Verschuldung von TB Ltd. liegt.\n\nMit Unterzeichnung dieses Vertrags, wird allen darin aufgelisteten Bedingungen zugestimmt.\n\n_________________\n\nUnterschrift", sourceObjective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", progress = "Wie steht's mit unserer Abmachung?", completion = "Es war ein Vergnügen mit Euch Geschäfte zu machen, {name}!\n\nIch wünsche Euch im Namen von TB Ltd. viel Glück bei Eurer Suche nach Sulfuras!", sourceObjectiveStatus = "unverified-source-field" }
quests[7621] = { id = 7621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Warnung", sourceObjective = "{class}, Ihr seid dabei eine entscheidene Reihe von Ereignissen zu durchleben, die alle Eure Fähigkeiten auf die Probe stellen sollen.\n\nIch schlage vor, dass Ihr Euch erst einmal anhört, was ich zu erzählen habe.\n\nLasst Euch gewarnt sein, Ihr müsst diese Aufgabe alleine lösen. Es ist ratsam, dass Eure Verbündeten Abstand halten. Die Einmischung anderer wird eine harte Bestrafung zur Folge haben.\n\nDas Schicksal hat Euch, Euch alleine, hierher geführt. Kämpft mit Ehre. Macht Euch das Licht zu Nutze.", sourceObjectiveStatus = "unverified-source-field" }
quests[7622] = { id = 7622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waage von Licht und Schatten", description = "Ihr müsst tun was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegen laufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr werdet versagt haben.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, {name}.", sourceObjective = "Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden.", progress = "Werdet Eurem Schicksal gerecht, {name}.", completion = "Eure Hartnäckigkeit und Euer Mut sind verblüffend, {class}. Ihr habt Euch das Recht den Splitter von Nordrassil tragen zu dürfen verdient. Es gilt nur noch eines zu tun: erlangt das Auge der Schatten wieder. Durchstreift die Welt danach.", sourceObjectiveStatus = "unverified-source-field" }
quests[7623] = { id = 7623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Schattenfluch", description = "Mor'zul sagte mir, dass Ihr ein Portal nach Xoroth öffnen möchtet. Für eine solche Aufgabe werdet Ihr xorothianischen Sternstaub benötigen und der ist nur schwer in Azeroth zu finden!\n\nAber es gibt jemanden, der welchen besitzen sollte: Lord Schattenfluch in Jaedenar, dem Sitz des Schattenrats! Sprecht mit ihm und vielleicht wird er Euch etwas Sternenstaub überlassen.\n\nDoch wenn Ihr nach Jaedenar wollt, solltet Ihr Euch mit dem gleichen Aroma des Bösen, das den Schattenrat umgibt, tarnen. Dazu werdet Ihr einige meiner schattenhaften Tränke brauchen und die sind nicht umsonst...", sourceObjective = "Erwerbt schattenhafte Tränke von Gorzeeki Wildaug beim Altar der Stürme in der Brennenden Steppe.\n\nBenutzt die Tränke um durch Jaedenar im Teufelswald zu reisen und sprecht mit Lord Schattenfluch in der Schattenfeste.", completion = "Meine Geduld umspannt Jahrtausende, {class}. Aber glaubt nicht das ich Euch mehr als einen kurzen Augenblick meiner Zeit widmen werde...", sourceObjectiveStatus = "unverified-source-field" }
quests[7624] = { id = 7624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulathek der Verräter", description = "Ihr wollt meine Gunst erlangen? Dann tötet für mich.\n\nMein Diener Ulathek treibt ein erbärmliches Spiel, während er wie ein elender Wurm vor mir kriecht, konspiriert er heimlich mit Lord Hel'nurath von Xoroth. Hel'nurath trachtet danach meine Macht an sich zu reißen und Ulathek ist sein Spion...\n\nBeweist mir, dass Ihr mir und nicht meinem Rivalen dient. Stellt Ulathek in seinem Quartier, der Schattenfeste im Osten. Macht ihm klar, dass ich sein kleines Geheimnis kenne und seht wie die Angst von ihm Besitz ergreift. Bringt mir anschließend das Herz des Verräters!", sourceObjective = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Schattenfluch in Jaedenar.", progress = "Ich schmecke bereits Ulatheks Herz. So süss ist das Herz des Verräters...", completion = "Herrlich! Nach einer Woche des Verfaulens, wird dieses Herz eine saftige Gaumenfreude sein! Vielleicht lasse ich mir noch Ulatheks Kopf bringen und platziere ihn vor mich, während ich esse...\n\nIhr habt mir einen großen Dienst erwiesen, {class} und meine Achtung vor Euch ist gestiegen, wenn auch nur unwesentlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[7625] = { id = 7625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xorothianischer Sternenstaub", description = "Ihr kommt also zu mir, weil Ihr xorothianischen Sternenstaub sucht? Ihr möchtet ein Portal nach Xoroth, dem Herrschaftsgebiet meines Rivalen Hel'nurath öffnen? Vielleicht plant Ihr sogar eines seiner geliebten Schreckensrösser zu stehlen?\n\nNun gut. Mein Diener Ur'dan hat einen Vorrat an Sternenstaub. Ihr könnt es von ihm bekommen... wenn ihr den Preis bezahlen könnt.", sourceObjective = "Erwerbt xorothianischen Sternenstaub von Ur'dan tief im Inneren der Schattenfeste in Jaedenar im Teufelswald. Bringt es anschließend Gorzeeki Wildaug in der Brennenden Steppe.", progress = "Wahrt Ihr schon in Jaedenar, {name}? Habt Ihr den Sternenstaub von Lord Banehollow bekommen?", completion = "Ihr habt ihn! Ich kann kaum glauben, dass Ihr ihn bekommen habt! Wie habt Ihr das geschafft? Seid Ihr einen Handel mit dem Schreckenslord eingegangen oder habt Ihr ihm ein Vermögen für den Sternenstaub angeboten? Vielleicht sogar beides?\n\nMor'zul wird seine Tinte schon bald haben und kann dann die Glyphenschriftrolle herstellen, mit deren Hilfe Ihr ein Portal nach Xoroth öffnen könnt, um eines der gefürchteten Schreckensrösser hindurch zu locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[7626] = { id = 7626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Glocke von Dethmoora", description = "Um einen mächtigen Beschwörungskreis herzustellen, benötigt man eine Glocke von Dethmoora, benannt nach dem uralten Hexenmeister Dethmoora Finsteraugen. Richtig abgestimmt mit dem Rad und der Kerze, speichern diese Gegenstände riesige Mengen arkaner Macht.\n\nMein Assistent Gorzeeki kann eine solche Glocke herstellen, allerdings benötigt er dafür einen großen Vorrat an Elixieren der Schattenmacht. Besorgt Euch die Elixiere von einem Alchemisten und bringt sie Gorzeeki.", sourceObjective = "Bringt 2 Elixiere der Schattenmacht zu Gorzeeki Wildaug in die Brennende Steppe.", progress = "Habt Ihr die Elixiere, {name}? Mor'zul sagte mir, dass Ihr eine Glocke von Dethmoora benötigt, doch um sie herzustellen bedarf es vieler Schattenenergien.", completion = "Sehr gut! Ich hoffe, Ihr hattet keine allzu großen Schwierigkeiten bei der Beschaffung der Elixiere. Manchmal sind Alchimisten sehr knauserig, wenn es um ihre Kreationen geht...\n\nIch werde die Glocke jetzt herstellen und sie aufbewahren, bis Ihr für das Ritual bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[7627] = { id = 7627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rad des Schwarzen Marsches", description = "Ein Rad des Schwarzen Marsches enthält und kontrolliert die gefährlichen Energien, welche für das Ritual des mächtigen Beschwörungskreises benötigt werden. Um das Rad zu konstruieren, benötigt Gozeeki große glänzende Splitter von einem Verzauberer und Dunkeleisen von einem Meisterbergmann.\n\nBeschafft diese Gegenstände und bringt sie meinem Assistenten.", sourceObjective = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildaug in die Brennende Steppe.", progress = "Es ist nicht leicht, ein Rad des Schwarzen Marsches herzustellen und es bedarf einer Vielzahl an Materialien. Habt Ihr alles bekommen?", completion = "Wie ich sehe, habt Ihr alles! Ich hörte, dass Dunkeleisenerz nur in den Blackrocktiefen zu finden ist, und ich bin mir sicher, dass es nicht viel einfacher war, an diese Splitter zu gelangen. Die Hingabe, mit der ihr {class} Eurer Tätigkeit nachgeht, beeindruckt mich immer wieder. Ihr solltet Eure Energien lieber in die Kunst des Käferfangens investieren, oh... einen solchen Schmaus würdet Ihr lieben!\n\nEntschuldigt, ich schweife vom Thema ab. Ich werde das Rad jetzt herstellen und es aufbewahren, bis Ihr für das Ritual bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
